(window.STORIES=window.STORIES||[]).push(...[{"n": 182, "l": "الجزء 156 | احداث السنه الثامنه من الهجرة | تعامل رسول الله مع اخطاء الصحابه", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وستة_وخمسون\n#أحداث_السنة_الثامنة_من_الهجرة\n#تعامل_رسول_الله_مع_أخطاء_الصحابة\nاتكلمنا في الأجزاء الأخيرة عن غزوة أو معركة مؤتة وعن السرايا إللي أخرجها رسول الله ﷺ بصفة عامة لخارج المدينة،\nهنتكلم بقى شوية عن الأحداث الداخلية\nعارفين طبعا الزبير بن العوام رضي الله عنه ابن عمة رسول الله ﷺ وحوارِيّ رسول الله ﷺ يعني ناصر رسول الله ﷺ  وخاصته من أصحابه لأنه من أقربهم إليه وأخلصهم له،\nوكمان هو واحد من العشرة المُبشرين بالجنة\nفي يوم من الأيام الزبير اختصم مع جار له من الأنصار من إللي حضروا غزوة بدر،\nالمشكلة كانت إن الزبير عنده أرض بيزرعها وبيسقيها بالماء، والأنصاري عنده أرض جنب أرض الزبير، لكن الزبير كانت أرضه أعلى شوية من أرض الأنصاري فكان الماء بيتسرب بسرعة لأرض الأنصاري ومش بيلحق الزبير يِروِي الأرض وكان الماء بيعدي في أرض الزبير الأول،\nفكان بيحبس الماء لحد ما الأرض بتاعته ترتروي وبعدين يرسل الماء لأرض الأنصاري،\nفالأنصاري اعترض وطلب منه إنه لا يحبس عنده المياه، فالزبير شرح له الموضوع لكن الأنصاري استمر على موقفه،\nفراحوا لرسول الله ﷺ عشان يحكم بينهم،\nوده كان عادة الصحابة لما كانت تحصل بينهم مشكلة كانوا بيرجعوا لرسول الله ﷺ عشان يحكم بينهم،\nوالمفروض ده كمان يكون منهجنا في الحياة، لو حصل بينا وبين أي حد خلاف نحتكم للقرآن وسنة رسوله ﷺ، وكلام ربنا ورسوله يمشي على الكل\nربنا بيقول:\n\"فَإِن تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِن كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ\"\nالمهم،\nراحوا لرسول الله ﷺ وحكوا له المشكلة، فرسول الله ﷺ  حكم وقال للزبير:\n\"اسْقِ يا زبيرُ\" يعني اسقِ انت الأول حاجة بسيطة أقل من حقك وبعدين أرسل الماء لجارك، يعني من باب المسامحة والصلح والتلطف بين الجيران، \nيعني الزبير هياخد أيسر كمية ممكن تكفيه وبعدين يرسل الماء لجاره،\nمع إن الزبير من حقه يسقي هو الأول لحد ما الأرض تستكفي الماء، لكن حكم رسول الله ﷺ ده عشان يراضي الطرفين بدون ظلم لواحد فيهم،\nلكن الأنصاري غضب وقال لرسول الله ﷺ كلمة شديدة\nقال: \n\" يا رسولَ اللَّهِ أَن كانَ ابنَ عمَّتِكَ؟! \"\nيعني بيقول لرسول الله ﷺ انت حكمت لصالحه عشان هو ابن عمتك يعني،\nطبعا الكلمة دي شديدة لأنه كده تعدّى على مقام النبوة وإن رسول الله ﷺ لم ينظر للمصلحة العامة ولكنه حابى لقريب من أقاربه وده طبعا لا يجوز بين عامة الناس إنهم يعملوا كده فما بالكم برسول الله ﷺ\nفرسول الله ﷺ لما سمع كلمة الأنصاري تغير وجهه وغضب وقال للزبير:\n\"يا زُبَيْرُ اسقِ ثمَّ احبِسِ الماءَ حتَّى يرجعَ إلى الجَدْرِ\"\nيعني بيقول للزبير إنه يسقي الأول وياخد حقه كااامل من المية وبعدين يبقى يرسل الماء للأنصاري،\nيعني رسولُ الله ﷺ هنا استوفى حق الزبير كامل ولم يترك منه شيء بعكس أول مرة لما كان بيحاول يصلح بينهما،\nقال الله:\n\"فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا فِي أَنفُسِهِمْ حَرَجًا مِّمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا\"\nيقول الزبير إنه يحسب إن الآية دي نزلت فيه هو وصاحبه الأنصاري،\nوالآية معناها :\nإن مفيش حد هيكون مؤمن غير لمّا يُحكّم رسول الله ﷺ في كل أموره ، وإللي يحكُم بيه رسول الله ﷺ هو الحق ولازم طاعة الحق ده والرضا به في الظاهر والباطن\n☆وهنا محتاجين وقفة نفهم بيها نقطة مهمة، الصحابة هم أفضل البشر بعد الأنبياء وفضلهم كبير جدا في نشر الدين،\nلأن الدين قام وانتشر على دمائهم وتضحياتهم، ومهما عملنا محدش فينا هييجي جنبهم حاجة زي ما رسول الله ﷺ قال :\n\" والَّذي نَفسي بيدِهِ لَو أنَّ أحدَكُم أنفَقَ مثلَ أُحُدٍ ذَهَبًا ما أدرَكَ مُدَّ أحدِهِم ولا نصيفَهُ\"\nيعني لو حد فينا أنفق أموال في سبيل زي جبل أُحد كده مش هييجي حاجة جنب واحد من الصحابة أنفق ملئ كفه أو نصفه في سبيل الله، حلو الكلام \nالصحابة بقى مش معصومين، يعني ممكن يقعوا في الخطأ وممكن يقعوا في الكبائر عادي جدا ولكنهم كانوا يتوبوا ويستغفروا بسرعة،\nده بالعكس بقى إن من حكمة ربنا إن الصحابة يقعوا في أخطاء عشان رسول الله ﷺ يصحّحها لهم وبعدين احنا نتعلم كمان نصلح أخطاءنا زيهم،\nفلما نقول يا جماعة إن الصحابة هم أفضل الناس وكان فيهم الصائم القائم العابد كذلك برده فيهم إللي زنا وفيهم إللي سرق وفيهم إللي كان بيشرب الخمر وفيهم ...وفيهم...\nولكن إللي كانوا بيقعوا في المحرمات والكبائر دول مكنوش بيقولوا زي ما الناس دلوقتي بتقول عادي يعني ما ربنا غفور رحيم\nلأ، الصحابة كانوا بيتوبوا ويستغفروا ويعملوا أعمال صالحة كتيييير عشان يكفّروا عن سيئاتهم\nفسيئاتهم غاااصت في بحر حسناتهم، زي الموقف إللي معانا دلوقتي، \nواحد من الأنصار من أهل بدر إللي هم أفضل البشر بعد الأنبياء على الإطلاق وربنا قال عنهم: \"اعملوا ما شئتم فقد غفرت لكم\"\nوقع في خطأ كبير جدا بسبب غضبه والشيطان خلّاه يظن إن رسول الله ﷺ ممكن يُحابي لحد من أقاربه،\nومع ذلك رسول الله ﷺ معلقلوش حبل المشنقة \nرسول الله ﷺ أه غضب ومنعه فضل كان أعطاه له لكن غضبه ﷺ مدفعهوش لظلم الصحابي ده والتعدي عليه\nوطبعا نتعلم هنا كمان إننا مهما حد تعدى علينا وأذانا وأغضبنا منتعداش عليه بظلم أكبر وناخد حق مش لينا،\nيعني مش زي ما في ناس تقول أنا برُد الصّاع صاعين، وإللي يديني قلم أديله اتنين والكلام إللي كله ظلم وانتقام للنفس وتعدي ده\nفالشاهد بقى من الكلام إننا لازم نتعلم حاجتين هم: \nفضل الصحابة وكمان أخطاء الصحابة وإزاي رسول الله ﷺ كان بيتعامل مع الأخطاء دي وإن خطأ الصحابي مش قَدْح فيه أبدا ولا تقليل من مكانته،\nفكل ما نتفهّم النقطة دي عن الصحابة ونعلمها لأولادنا مش هيبقى فيه صدمة نفسية من ناحية الصحابة\nيعني مثلا تخيلوا كده لما الطفل يكبر وهو يسمع عن بطولات الصحابة وصدقهم وبذلهم وتضحياتهم وبعدين ييجي يسمع فجأة كده إن واحد من الصحابة دول كان بيشرب الخمر أو واحد منهم زنى، أو واحد منهم اعترض على حكم رسول الله ﷺ هيكون مشاعره إيه\nأكيد هتحصل صدمة نفسية ممكن توصله إنه يكره الصحابة، يعني إزاي الناس الأبطال دول يقعوا في أخطاء أنا مثلا مستحيل أعملها\nفالإحساس ده يخلي صورة الصحابة مهزوزة عند الناس،\nفعشان كده لازم نعرف الجانبين:\nجانب البطولة والبذل والتضحية وجانب الأخطاء إللي الصحابة وقعوا فيها وإنهم مش معصومين وإنّ كان طبيعي جدا جدا إنهم يقعوا في الغلط عشان الأجيال إللي تيجي بعدهم وتكرر نفس الغلط يعرفوا إزاي يصلحوا الغلط زي ما رسول الله ﷺ علّم الصحابة\nوشوفوا رد فعل رسول الله ﷺ لما الصحابة ضحكوا على عبد الله بن مسعود كان إيه\nكان عبد الله بن مسعود دقيق الساقين يعني رجله رفيعة جدا، وكان طلع على شجرة آراك يجيب سواك لرسول الله ﷺ فكانت الريح بتلعب برجله وتحركها،\nفضحك الصحابة عليه ودي سخرية أهه وخطأ منهم، فقال لهم رسول الله ﷺ:\nما يُضحِككم ؟! يعني إيه إللي بيضحكم، قالوا:\n\"لدِقَّةِ ساقِهِ\"\n يعني احنا بنضحك على رجله الرفيعة دي، فقال لهم:\n\" لهُما أثقَلُ في الميزانِ مِن أُحُدٍ\"\nيعني ساقه إللي انتم شايفينها رفيعة دي هي أثقل عند ربنا من جبل أحد، يعني لما يكون إنسان ظاهره الصلاح والتقوى لكنه ضعيف الجسم مثلا انتم متحكموش عليه بالشكل ولا تسخروا منه؛\nلأن ممكن يكون له أعمال خفية أو له فضل انتم متعرفهوش، وتكون مكانته عند ربنا أعظم ما تتخيلوا\nفهنا الصحابة أخطأوا ورسول الله ﷺ عالج خطأهم، ومحدش ضحك على دقة ساق عبد الله بن مسعود مرة تانية،\nفالمشكلة مش في الخطأ لكن المشكلة هل إللي بيعمل الخطأ ده تاب عنه وصلّحه ولّا لأ\nوشوفوا القصة دي كمان، واحد من الصحابة جاء لرسول الله ﷺ وقال له:\n\"يَا رَسُولَ اللَّهِ!\n\" إِنِّي عَالَجْتُ امْرَأَةً فِي أَقْصَى الْمَدِينَةِ وَإِنِّي أَصَبْتُ مِنْهَا مَا دُونَ أَنْ أَمَسَّهَا فَأَنَا هَذَا فَاقْضِ فِيَّ مَا شِئْتَ\"\nيعني بيقول له إنه عمل معصية مع امرأة لا تحل له، سواء بقُبلة أو مسّها بيده، لكنه لم يفعل معها الفاحشة،\nفجاء لرسول الله ﷺ عشان يقول له الحل يعمل إيه عشان يكفّر عن الذنب ده، لأنه حاسس إنه عمل جريمة كبيرة،\nفكان موجود في المجلس عمر بن الخطاب رضي الله عنه فقال له:\n\" لَقَدْ سَتَرَكَ اللَّهُ لَوْ سَتَرْتَ نَفْسَكَ\"\nيعني ربنا سترك، كنت استر على نفسك انت كمان ومتجبش سيرة عن الموضوع،\nوالرجل مستني رد رسول الله ﷺ، لكن رسول الله ﷺ سكت ومردش على الرجل، لأن مفيش وحي كان نزل لحد الموقف ده يقول الحل إيه، \nورسول الله ﷺ مينفعش يجتهد ويقول أي حاجة من عنده وكمان لا ينطق عن الهوى، فالرجل لما لقى رسول الله ﷺ مردش عليه ومفيش إجابة قام مشي وهو مهموم،\nفأرسل رسول الله ﷺ خلفه رجل ينادي عليه، فرجع الصحابي لرسول الله ﷺ فتلى عليه رسول الله ﷺ آية :\n\" أَقِمْ الصَّلاةَ طَرَفَيْ النَّهَارِ وَزُلَفًا مِنْ اللَّيْلِ إِنَّ الْحَسَنَاتِ يُذْهِبْنَ السَّيِّئَاتِ ذَلِكَ ذِكْرَى لِلذَّاكِرِينَ\"\nيعني صلي الصلوات وأكثر من النوافل وصل قيام الليل، الصلوات دي هتكفر الذنوب؛ لأن الحسنات بتمسح السيئات،\nفواحد من الصحابة يُقال إنه كان معاذ بن جبل لما سمع كلام رسول الله ﷺ سأله:\nيا نبي الله هذا له خاصة؟\nيعني الحل ده له هو بس ولّا للناس كلها، فقال له رسول الله ﷺ: \" بل للناس كافة\"\nيعني أي حد يعمل ذنب فيُسارع بعمل الصالحات لحد ما يكفر عن ذنبه إللي عمله\nزي مانتم شايفين أهه، مجتمع الصحابة مكنش مجتمع ملائكة ومبيغلطوش\n لأ، بيغلطوا لكن بيعالجوا الخطأ وبيسارعوا في عمل الصالحات\nتخيلوا بقى لو الموقف ده مكنش حصل والموقف ده يُعتبر مش بسيط، فاحنا كنا هنعرف الحل إزاي\nلازم الموقف يحصل عشان ربنا ينزّل الآيات أو الوحي المناسب للموقف ده عشان لما يتكرر نعرف نعالجه،\nولو أخدتم بالكم، موقف عمر بن الخطاب رضي الله عنه من الرجل لما قال له كنت استر على نفسك، \nفي ناس في عصرنا دلوقتي بيقولوا نفس جملة عمر رضي الله عنه، يعني لما حد ييجي يسأل يا جماعة أنا عملت كذا إيه الحل، \nنلاقي ناس ترد وتقول استر على نفسك، لو فعلا كان الأولى إنه يسكت ويستر على نفسه كان رسول الله ﷺ أكد على كلام عمر رضي الله عنه وقال للرجل استر على نفسك ومتقولش ذنبك\nوفي نفس الوقت رسول الله ﷺ مأنكرش على عمر كلامه، فده معناه إيه بقى\nمعناه إن الأصل إن الإنسان يستر على نفسه ويتوب بينه وبين ربنا زي ما عمر قال،\n لكن لو الواحد عمل ذنب ومش عارف يتوب إزاي أو إيه التصرف المناسب، يبقى هنا يسأل أهل الاختصاص يعمل إيه  زي ما الصحابي جاء سأل رسول الله ﷺ كده\nمن الأحداث إللي حصلت في المدينة برده إسلام أم أبي هريرة\nكنا قلنا قبل كده قصة إسلام أبو هريرة وإنه بعد إسلامه جاء للمدينة وفضل مُلازم لرسول الله ﷺ وبيقعد يسمع كلامه،  أبو هريرة كان بار جدا بأمه، بيسمع كلامها ويراعيها ويخدمها، فلما أسلم وهاجر جاءت أمه معاه للمدينة وكانت مشركة، فكان بيدعوها للإسلام لكنها كانت بترفض،\nففي يوم دعاها للإسلام فتكلّمت عن رسول الله ﷺ بكلام كرهه أبو هريرة فسابها ومشي وراح لرسول الله ﷺ وهو بيبكي وقال له:\n\" يا رسول الله، إني كنت أدعو أمي إلى الإسلام فتأْبى علي، فدعوتها اليوم فأسمعتني فيك ما أكره، فادع الله أن يهدي أم أبي هريرة\"\nيعني هو حكى له إن أمه بترفض الإسلام فطلب من رسول الله ﷺ إنه يدعي لأمه بالهداية،\nفقال رسول الله ﷺ:\n\" اللهم اهدِ أم أبي هريرة\"\nفخرج أبو هريرة من عند رسول الله ﷺ وهو فرحان ومستبشر بدعوة رسول الله ﷺ وراح بيته،\nفلما وصل لباب البيت لقاه مقفول، فأم أبو هريرة سمعت صوت أقدام أبو هريرة عند الباب فخافت أحسن يفتح الباب ويدخل فقالت :\n\" مكانك يا أبا هريرة\" يعني خليك زي مانت متدخلش، فأبو هريرة استغرب هي أمه مش عايزاه يدخل ليه فسمع صوت خَضْخَضَةُ الماء،\nيعني سمع صوت مية بتتحرك، فعرف إنها بتغتسل، فلما اغتسلت لبست ملابسها وراحت فتحت الباب لأبي هريرة وقالت له:\n\"يا أبا هريرة، أشهد أن لا إله إلا الله، وأشهد أن محمدًا عبده ورسوله\"\nفرح أبو هريرة جدا بإسلام أمه، ورجع لرسول الله ﷺ وهو بيبكي من الفرح وقال لرسول الله ﷺ:\n\" يا رسول الله!\nأبْشِر قد استجاب الله دعوتك وهدى أم أبي هريرة\"\nففرح رسول الله ﷺ طبعا وحمد الله وأثنى عليه وقعد يتكلم مع أبو هريرة بكلام طيب،\nوبعدين أبو هريرة قال لرسول الله ﷺ :\n\"يا رسول الله!\n ادع الله أن يُحببني أنا وأمي إلى عباده المؤمنين، ويحببهم إلينا\"\nيعني هو عايز رسول الله ﷺ يدعو له إن المؤمنين يحبوه هو وأمه وهم كمان يحبوا المؤمنين،\nفقال رسول الله ﷺ:\n\"اللهم حبب عُبَيْدك هذا -يعني أبا هريرة- وأمه إلى عبادك المؤمنين، وحَبّب إليهم المؤمنين\"\nفقال أبو هريرة :\n\" فما خُلقَ مؤمن يسمع بي ولا يراني إلا أحبني\"\nيعني أي مؤمن يتخلق أو يقابل أبو هريرة أو يشوفه أو يسمع عنه إلا ويحبه على طول ببركة دعوة رسول الله ﷺ \n☆سؤال بقى : هل حب المؤمنين ده خاص بزمن أبو هريرة ولّا حتى بعد زمانه\nظاهر الحديث إن دعوة رسول الله ﷺ لأبي هريرة وأمه مش بس في حياته ولكن للأبد؛\nلأن لفظ المؤمنين في كلام رسول الله ﷺ بيدل على العموم، والعموم يعني في كل الأزمان، \nوبالتالي أي حد يكره أبو هريرة وأمه أو يُشكك في روايات أبي هريرة للحديث أو يطعن عليه فده يبقى عنده مشكلة في الإيمان وإيمانه في خطر\nوبما إننا بنتكلم عن أبي هريرة رضي الله عنه وروايته للحديث فخلونا نعرف إزاي حفظ كمية الأحاديث دي كلها\nقلنا قبل كده إنه كان مُلازم لرسول الله ﷺ فكان بيسمع منه أحاديث منه ﷺ أكتر من باقي الصحابة،\nلكن كان عنده مشكلة وهي مشكلة الحفظ، يعني بيسمع كلام رسول الله ﷺ لكنه بينساه،\nفاشتكى لرسول الله ﷺ وقال له:\nيا رَسولَ اللَّهِ!\n إنِّي أسْمَعُ مِنْكَ حَدِيثًا كَثِيرًا أنْسَاهُ؟ \nيعني انا بسمع منك أحاديث كتيرة ولكني بنساها، أعمل إيه؟!\nقال له رسول الله ﷺ:\n\"ابْسُطْ رِدَاءَكَ\"\nيعني افرد الرداء بتاعك، فبسطه أبو هريرة وقال أبو هريرة عن رسول الله ﷺ إنه \"غَرَفَ بيَدَيْهِ\" ثُمَّ قَالَ رسول الله ﷺ لأبي هريرة: ضُمَّهُ، فَضَمّه أبو هريرة، وقال عن نفسه: \n\"فَما نَسِيت شيئًا بَعْدَه\" \nيعني بعد الموقف ده لم ينس أبو هريرة أي حديث قاله رسول الله ﷺ،\nطبعا مش مذكور غَرَف إيه وغرف فين\nهي إشارة فقط بالغَرْف زي ما جاءت في الحديث\nودي معجزة من معجزات رسول الله ﷺ وكرامة لأبي هريرة رضي الله عنه\nالمهم بقى في وسط انشغال رسول الله ﷺ بأحوال الصحابة الداخلية جاله خبر إن قبيلة قضاعة جمعت مجموعة عشان يهجموا على المدينة،\nفاكرين قبيلة قُضاعة\n إللي قتلت أربعة عشر رجلا من المسلمين ورسول الله ﷺ كان أرسل لهم سرية وملقاش الناس إللي قتلوا الصحابة دول وبعدين حصلت معركة مؤتة،\n أهم جايين يعملوا مشاكل تاني مع المسلمين، ياترى رسول الله ﷺ هيكون رد فعله إيه،\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 183, "l": "الجزء 157 | احداث السنه الثامنه من الهجرة | سرية ذات السلاسل", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وسبعة_وخمسون\n#أحداث_السنة_الثامنة_من_الهجرة\n#سرية_ذات_السلاسل\nاتكلمنا قبل كده في الجزء المائة واثنان وخمسون عن إن  قبيلة قضاعة قتلت أربعة عشر رجلا من أصحاب رسول الله ﷺ،\nوقلنا إن رسول الله ﷺ كان لازم ياخد معاهم موقف حازم،\nولكن كانت حصلت مشكلة تانية مع الغساسنة وقبائل شمال شبه الجزيرة العربية فقرر رسول الله ﷺ إنه يتعامل مع كل مشكلة لوحدها وبدأ بقبائل شمال شبه الجزيرة العربية وحصلت معركة مؤتة،\nالمشكلة التانية بقى كانت قبيلة قضاعة، وواضح إن قبيلة قضاعة لما شافوا إنهم قتلوا أربعة عشر رجل من الصحابة فكروا نفسهم أقوياء وهيقدروا يهجموا على المدينة وينتصروا على المسلمين\nفبدأوا يجهزوا جيش لغزو المدينة، رسول الله ﷺ وصل له الخبر وهو أصلا كده كده مكنش هيسيبهم\nفجهز رسول الله ﷺ جيش للخروج لقتال قبيلة قضاعة،\nوالمنطقة إللي بتعيش فيها قضاعة كان اسمها ذات السُّلاسِل، واتسمت كده عشان المكان ده كان ماء اسمه السُّلسَل، \nأو ذات السَّلاسِل لأن الأرضَ إللي كانوا فيها كانت ذاتَ رَملٍ يَنعقِدُ بعضُه على بَعضٍ كالسِّلسلةِ،\nوكان وقت السرية دي في شهر جُمادى الآخرة من السنة الثامنة من الهجرة، وكان عدد السرية ثلاثمائة رجل من الصحابة،\nمين بقى القائد إللي رسول الله ﷺ اختاره عشان يقود السرية دي\nأَرْطبون العرب عمرو بن العاص رضي الله عنه \nرسول الله ﷺ لما اختار عمرو مكنش اختيار عشوائي أبدا بالعكس ده اختيار في منتهى الحكمة من رسول الله ﷺ،\n اختاره هو بالذات لأنه أكتر واحد يقدر يقوم بالمهمة دي\nليه\n◇اولا:\n أم عمرو بن العاص من قبيلة قُضَاعة، وبالتالي هو راح القبيلة دي قبل كده وأعرف الناس بالطرق إللي بتؤدي لهناك أكثر من بقية الصحابة،\nوحاجة أهم وهي إن كون أم عمرو من قضاعة وهم عارفين عمرو فلعل يحصل بينهم وبين عمرو حوار ومفاوضات عن الإسلام فيقبلوا بالدخول في الإسلام،\nواحنا عارفين إن رسول الله ﷺ كان همه إن الناس يدخلوا في الإسلام أكتر من أي شيء تاني\nده غير طبعا قدرته ودهائه العسكري \n◇ثانيا:\nرسول الله ﷺ كان عايز يتألّف قلب عمرو بن العاص رضي الله عنه ويعطي له مكانة في الإسلام زي ما كان له مكانة كبيرة عند قريش قبل إسلامه،\nيعني بالبلدي كده كأن رسول الله ﷺ بيقول له انت خبراتك وعقليتك وطاقتك مش  هتضيع في الإسلام، ولا انت عشان كنت بتحارب الإسلام سنين طويلة يبقى هنركنك على جنب ومش هيبقى ليك لازمة،\nوعمرو بن العاص كان شخصية رئيسية مهمة جداً في مكة وكانت قريش تعتمد عليه اعتماد كبير جدا وعلى خبراته\nفإسلامه وانضمامه لجيش المدينة يعتبر إضافة كبيرة جداً للمسلمين لازم يحافظ عليها المسلمون عشان يقدروا يستفيدوا من خبراته دي أقصى استفادة،\nوانتم عارفين الواحد لما يحس إن إللي حواليه مقدّرين مكانته، وشايف إن مجهوده مبيرحش في الأرض هنلاقيه بيجتهد عشان يطلع أحسن ما عنده\nومننساش إن خالد بن الوليد إللي كان أسلم مع عمرو بن العاص بقى له مكانة وقدر عالي بين المسلمين بعد معركة مؤتة، ورسول الله ﷺ سماه سيف الله،\nفرسول الله ﷺ كان عايز يعطي عمرو مكانة وسط المسلمين زي خالد كده\nلما اختار رسول الله ﷺ عمرو بن العاص قائد للمهمة دي،\nكان عايز يبلغه بقى بالمهمة دي فأرسل له رجل يقول له:\n\"خُذ عليك ثيابَك وسلاحك ثم ائتني\"\nيعني البس ملابس الحرب وجهز سلاحك واذهب لرسول الله ﷺ ، فجاء عمرو بن العاص لرسول الله ﷺ فلقاه بيتوضى فنظر له رسول الله ﷺ ودقَّقَ فيه النظر وبعدين وطّى رأسه وقال له:\n\"إني أريد أن أبعثك على جيش فيُسلّمك الله ويُغنمك، وأرغب لك من المال رغبة صالحة\"\nيعني انت هتقود الجيش في السرية إللي خارجة دي، وربنا هينصرك وكمان هتاخد غنائم وهيبقى عندك مال كتير،\nفقال عمرو لرسول الله ﷺ:\n\"يا رسول الله، ما أسلمتُ من أجل المال ولكني أسلمت رغبة في الإسلام، وأن أكون مع رسول الله ﷺ\"\nيعني انا مدخلتش الإسلام عشان عايز أموال، أنا أسلمت رغبة في الإسلام نفسه وعشان أكون مع رسول الله ﷺ،\nولو عمرو مكنش صادق ومخلص فعلا كان زمان الوحي نزل وقال إنه بيكذب\nفرسول الله ﷺ قال له:\n\" يا عمرو نِعْم المالُ الصالحْ للمَرْء الصالح\"\nيعني المال الحلال نعمة إذا وقع بيد الرجل الصالح؛ لأنه بيبتغي به وجه الله ويصرفه في وجوه الخير ويعف به نفسه وأسرته،\nفدي شهادة من رسول الله ﷺ بإن عمرو بن العاص رجل صالح، وده رد على الناس إللي بتطعن وبتتكلم كلام سيء على عمرو بن العاص\nرسول الله ﷺ بنفسه وهو لا ينطق عن الهوى شهد لعمرو بإنه رجل صالح\nعمرو بن العاص خرج مع السرية إللي كانت مكونة من ثلاثمائة رجل من المهاجرين والأنصار باتجاه قبيلة قضاعة في منطقة ذات السلاسل زي ما قلنا،\nومع إن عمرو بن العاص لسه مبقالوش غير أربعة شهور في الإسلام إلا إن مفيش واحد من الصحابة اعترض وقال إزاي عمرو يكون قائد علينا واحنا إللي لينا تاريخ طويل في الإسلام وهو معندوش خبرة زينا والمفروض الأقدم هو إللي يكون القائد و...و...\nوكان بعض الصحابة وصل تاريخه في الإسلام لعشرين سنة، لكن مع كل ده محدش اعترض،\nالصحابة مكنوش بيدوّروا على المناصب كان همهم المصلحة العامة للإسلام والمسلمين،\nكان همهم إن راية الإسلام تترفع مش مهم مين إللي يرفعها\nخرج الجيش من المدينة، ومن أول لحظات الخروج ظهرت عبقريته رضي الله عنه في الحروب\nمن أول الطريق قرر إنه يسير بالمسلمين ليلاً ويَكمُن نهاراً، عشان عيون العدو متكتشفش جيش المسلمين،\nولو تفتكروا دي كانت طريقة القادة المسلمين إللي خرجوا للقتال في السرايا إللي قبل كده زي زيد بن حارثة،\nلكن ده كان أول قتال لعمرو مع المسلمين فاتبع هو كمان نفس المنهج من غير ما حد يقوله عليه\nوفعلا وصل جيشه لمنطقة ذات السلاسل من غير ما قضاعة تعرف حاجة عن الجيش،\nوبدأ يرسل عيون هنا وهناك عشان يعرف أخبار جيش قضاعة ويعرف عدد الجيش بتاعهم،\nفلقى إن عدد جيش قضاعة كبير والعدد إللي معاه صغير ومش هيقدر يواجه بيه الأعداد الكبيرة دي كلها\nوعمرو كان واقعي جدا ومكنش متهور أبدا، وكان قبل ما يدخل أي قتال لازم يكون دارسه وفاهم كويس أوي هو هيقاتل إزاي\nفلما لقى الأعداد كبيرة أرسل رسالة لرسول الله ﷺ في المدينة يطلب فيها المدد،\nيعني عايز من رسول الله ﷺ إنه يرسل له جيش تاني يساعده، طبعا ده كان بعكس الأحداث في مؤتة،\nقلنا إن المسافة كانت بعيدة جدا عن المدينة فمفيش مجال إن حد يروح يوصل رسالة لرسول الله ﷺ يطلب منه المدد\nيعني المسافة بين المدينة وبين قضاعة كانت عشر أيام فقط بعكس مؤتة كانت شهر رايح جاي\nعمرو رضي الله عنه أمر جيش المسلمين إللي معاه إنهم ميقاتلوش والقتال هيبدأ لما يأتي المدد من المدينة،\nوصلت رسالة عمرو لرسول الله ﷺ فجهز رسول الله ﷺ سرية من مائتين رجل من الصحابة بقيادة أبو عبيدة عامر بن الجراح وفي السرية كان أبو بكر وعمر رضي الله عنهم أجمعين، وأوصى رسول الله ﷺ أبو عبيدة وقال له:\n\"إذا قَدِمت على صاحبك فتَطَاوَعا ولا تَخْتَلِفا\"\nيعني لما توصل لجيش عمرو اتفقوا مع بعض وتجنبوا الخلاف\n☆ملحوظة يا جماعة صحيح\nأبو عبيدة بن الجراح متسمّاش كده عشان كان عنده جروح كثيرة \nهو أبوه اسمه الجرّاح، فبقى اسمه عامر بن الجراح فهو مكنش لقبه الجرّاح، ، يعني مش زي أبو بكر الصديق مثلا، أو عمر الفاروق، لأ، أبو عبيدة بن الجراح رضي الله عنه وكان لقبه أمين الأمة أو الأمين\nوصل أبو عبيدة رضي الله عنه ومعاه المائتين مقاتل لمكان جيش عمرو في ذات السلاسل، فلما جاء وقت الصلاة قام أبو عبيدة عشان يصلي بالناس إمام، لأن قائد الجيش هو إللي يصلي بالناس،\nفهنا عمرو رضي الله عنه قال له لأ، أنا إللي هصلي بالناس لأن أنا قائد الجيش وانت جيتلي مدد، \nفقال المهاجرون لأ، كده يبقى كل واحد أمير أو قائد الجيش بتاعه، يعني عمرو هو قائد الثلاثمائة،\nوأبو عبيدة قائد المائتين، فعمرو قال لأ، هو جالي مدد يبقى يدخل مع الثلاثمائة ويبقى زيه زيهم\nفقال له أبو عبيدة رضي الله عنه:\n\"لتطمئن يا عمرو، وتعلمَنّ أن آخر ما عهد إليّ رسول الله أن قال: إذا قدمت على صاحبك فتطاوعا ولا تختلفا، وأنك والله إن عصيتني لأُطِيعَنك\"\nيعني بيقول له متخفش يا عمرو اطمن، أنا مش ناوي أعمل مشاكل، واعرف إن آخر حاجة وصاني بيها رسول الله ﷺ قبل ما أسيب المدينة إني مختلفش معاك ونتفق،\nوانت لو مسمعتش كلامي أنا هسمع كلامك\nودي من حكمة أبو عبيدة رضي الله عنه؛ لأنه عارف إنه لو حصل أي اختلاف داخلي دلوقتي بين المسلمين النتيجة هتكون هي الفشل وبالتالي العدو هيتغلب عليهم ويهزمهم،\nوربنا بيقول:\n\" وَلَا تَنَازَعُوا فَتَفْشَلُوا وَتَذْهَبَ رِيحُكُمْ\"\n☆محدش يفهم رد فعل عمرو رضي الله عنه غلط يا جماعة\nيعني عمرو مكنش حريص على الإمارة عشان كده صمم يعني إنه يكون هو القائد، لأ، هو كان شايف إن دي مهمة أعطاها له رسول الله ﷺ ولازم ينفذها وهو ﷺ إللي خلاه قائد للجيش،\nومفيش امر مباشر من رسول الله ﷺ إن أبو عبيدة يكون هو القائد\nوهو أصلا يستحق الإمارة دي لأنه اكبر في السن من أبي عُبيدة وكان عنده خبرة عسكرية وعبقري في إدارة الجيوش،\nفهو شايف إنه لازم يؤدي المهمة دي على أكمل وجه فعشان كده صمم إنه يكون هو قائد الجيش،\nوانتم هتشوفوا بنفسكم عبقريته في قيادة الجيش في السرية دي\nبدأ عمرو يصلي بالصحابة كل الصلوات، والجيش فيه أبو بكر وعمر وأبو عبيدة وكبار الصحابة من المهاجرين والأنصار،\nكل دول بيصلوا وراء عمرو إللي لسه كان مسلم من أربعة شهور فقط عادي جدا\nبجد صورة حضارية رائعة في تاريخ المسلمين، ومظهر من مظاهر الوِحدة، \nوده من أهم أسباب النصر، الكل بيعمل في سبيل الله محدش بيجري ورا الإمارة والمنصب الكل عايز المصلحة العامة لجيش المسلمين\nطبعا بعكس الواقع بتاعنا دلوقتي، كله بيدور على المنصب والقيادة عشان يثبت نفسه أو عشان مصلحته الشخصية ومش فارق معاه هموم المسلمين ومشاكلهم، وده من أسباب التفرّق والخذلان إللي المسلمين فيه\nالمشكلة بقى إن الموضوع موقفش على كده بين عمرو رضي الله عنه وبين الصحابة \nيعني ده أول موقف يحصل فيه زي مشادة كده وخلاص الحمد لله اتحل،\nالموقف التاني إللي حصل إن المسلمين كانوا عايزين يُوقدوا نار عشان يتدفوا،\nعارفين يعني يجيبوا خشب ويولعوا فيه عشان يتدفوا من النار إللي طالعة، لكن عمرو رضي الله عنه رفض إنهم يوقودوا النار وقال لهم : لا توقدوا النار\nوالليلة دي بالذات كانت ليلة شديدة البرودة،\nوبرد الصحراء حاجة صعبة\nفالصحابة راحوا لأبي بكر الصديق رضي الله عنه يشتكوا له ويطلبوا منه إنه يتوسط لهم عند عمرو عشان يوافق إنه يخليهم يوقدوا النار، \nوطبعا محدش يقدر يخالف القائد، لا يجوز مخالفة قائد الجيش مادام لم يأمر بمعصية الله أو أمر بشيء الجنود ميقدروش عليه\nلأن الطاعة في المعروف والاستطاعة\nكلم أبو بكر الصديق رضي الله عنه عمرو بن العاص في إيقاد النار لكن عمرو قال بكل حزم\n:\nلا يُوقد أحد منكم ناراً إلا قذفته فيها\nيعني إللي فيكم هيولع نار هرميه فيها\nأنا بصراحة مش متخيل منظر الصحابة وهم بيسمعوا الكلام ده، أول مرة يحصل معاهم كده\nحتى عمر رضي الله عنه راح اتكلم مع أبو بكر في الموضوع وإزاي عمرو يعمل كده مع الناس،\nلكن أبو بكر رضي الله عنه رد عليه رد في منتهى اليقين والثقة في رسول الله ﷺ \n قال:\n\"إن الرسول ﷺ أمّره على الجيش وهو أعلم\"\nيعني رسول الله ﷺ  أعلم بحكمة عمرو وبقدرته على إدارة الجيش، واحنا ملناش غير إننا نسمع ونطيع حتى لو معرفناش الحكمة من الأمر إللي اتقال،\nحصل القتال بين جيش المسلمين وبين قبيلة قُضاعة واستطاع عمرو بن العاص بخطة عسكرية بارعة إنه يحقق نصر كبير جدا على قبيلة قضاعة،\nواتكرر من جديد نصر مؤتة، يعني عدد صغير من المسلمين انتصر على عدد كبير من قبيلة قضاعة،\nوبعد ما انتصر الصحابة، قبائل قضاعة تفرقوا وهربوا هنا وهناك، فالصحابة اتحمسوا وكانوا عايزين يروحوا يطاردوهم،\nفعمرو بن العاص منعهم، وقال إن محدش يطار الجيش الهارب من قضاعة، \nفالصاحبة سمعوا كلام عمرو اضطروا للرجوع وهم محتارين ومش عارفين السبب إللي خلى عمرو يمنعهم من مطاردة الهاربين دول\nوده كده تالت موقف يحصل ويعمل أزمة\nفي ليلة من ليالي السرية عمرو بن العاص احتلم فأصبح على جنابة، فالمفروض إنه يغتسل الأول عشان يعرف يصلي،\nلكنه تيَمّم فقط وصلى بالناس بالتيمم،\nطبعا الصحابة استغربوا، انت اتيممت وفي ماء إزاي\nإذا حضر الماء بطُل التيمم، مينفعش تتيمم وفي ماء،\nوهو مصمم وصلى بالناس كده بدون غُسل أو وضوء،\nوده كده موقف رابع، يعني أنا متخيل إن الصحابة كانوا بيغلوا في الوقت ده\nلأن همّ أقدم من عمرو في الإسلام وعارفين أحكام الإسلام وهو لسه جديد فالمفروض يسمع كلامهم، \nوالجيش فيه أبو بكر وعمر وكبار الصحابة، لكن هو كان مصمم على رأيه رضي الله عنه \nالمهم، السرية خلصت ورجع الجيش للمدينة، واتسمت السرية باسم سرية ذات السلاسل،\nوطبعا سرية ذات السلاسل دي إللي كانت بقيادة عمرو بن العاص غير معركة ذات السلاسل إللي كانت بقيادة خالد بن الوليد في السنة الثانية عشرة من الهجرة وكانت بين المسلمين وبين الفُرس، فمحدش يتلغبط\nالصحابة بعد ما رجعوا للمدينة ماستحملوش \nعلى طول راحوا لرسول الله ﷺ يشتكوا له من عمرو من بن العاص إنه منعهم إنهم يُوقدوا النار،\nومنعهم إنهم يطاردوا الفارين من المشركين، وصلى متيمما وكان في ماء،\nفرسول الله ﷺ بدأ يسأله عن الأسباب إللي خلته يعمل كده،\nفبدأ عمرو بن العاص رضي الله عنه يشرح وجهة نظره قال عن منعهم لإيقاد النار:\n\"كرهت أن آذن لهم أن يوقدوا ناراً فيرى عدوهم قلتهم\"\nيعني هو خاف لو ولعوا النار عدوهم يعرف مكان جيش المسلمين ويعرفوا عددهم وبالتالي يحاوطوا المسلمين ويقتلوهم\nوبالنسبة لرفضه إن المسلمين يتبعوا الهاربين من قضاعة قال:\n\" يا رسول الله كرهت أن يتّبعوهم فيكون لهم مدد\"\nيعني هو خاف إن قبائل قضاعة يكون لهم مدد والمسلمين ميعرفوش، فقبيلة قضاعة ترتب صفوفهم ويهاجموا المسلمين إللي خرجوا وراهم ويقتلوهم،\nوالأمر الثالث إنه صلى بالناس وهو متيمم مع وجود الماء قال لرسول الله ﷺ:\n\"يا رسول الله!\n إني سمعت الله يقول:\n\"وَلا تَقْتُلُوا أَنفُسَكُمْ إِنَّ اللَّهَ كَانَ بِكُمْ رَحِيمًا\" \nوالليلة دي كانت ليلة شديدة البرودة فخفت على نفسي إني لو اغتسلت بالماء البارد أموت،\nفهنا رسول الله ﷺ ضحك ومقلش حاجة وأقر عمرو بن العاص على كل إللي عمله وطلع هو إللي وجهة نظره كانت صح \nسبحان الله مع إن الجيش كان فيه كبار الصحابة إللي بقالهم سنين طويلة في الإسلام ومع ذلك خَفِي عليهم وجهة نظر عمرو رضي الله عنه \nوبكده انتهت سرية ذات السلاسل، عمرو لما لقى رسول الله ﷺ جعله قائد على جيش فيه أبو بكر وعمر وكبار الصحابة نفسه قالت له إنه أكيد له منزلة عالية عند رسول الله ﷺ لأنه قدّمه على أصحابه الكبار دول،\nفسأل عمرو رضي الله عنه رسول الله ﷺ سؤال قال.....\nقال له إيه\nهنعرف المرة الجاية إن شاء الله"}, {"n": 184, "l": "الجزء 158 | احداث السنه الثامنه من الهجرة | يوم في حيات النبي", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثمانية_وخمسون\n#أحداث_السنة_الثامنة_من_الهجرة\n#يوم_في_حياة_النبي\nقلنا المرة إللي فاتت إن عمرو بن العاص لما لقى رسول الله ﷺ خلّاه قائد على جيش فيه أبو بكر وعمر وكبار الصحابة، نَفْسُه قالت له إنه أكيد له منزلة عالية عند رسول الله ﷺ لأنه قدّمه على أصحابه الكبار دول،\nفسأل عمرو رضي الله عنه رسول الله ﷺ سؤال قال:\n\"أَيُّ النَّاسِ أَحَبُّ إِلَيْكَ؟ \"\nيعني مين أكتر حد انت بتحبه، هو مسألوش انت بتحبني ولّا لأ، لأنه عارف إن رسول الله ﷺ بيحب كل الصحابة، لكن هو عايز يعرف هو رقم كم عند رسول الله ﷺ في المنزلة فسأله السؤال بالطريقة دي\nفرد عليه رسول الله ﷺ وقال له:\nعَائِشَةُ!\nفقال له عمرو: مِنَ الرِّجَالِ؟ \nيعني انت بتحب مين من الرجال أكتر واحد، فقال له رسول الله ﷺ:\nأَبُوهَا، فقال له عمرو : ثُمَّ مَنْ؟\nيعني مين تاني واحد بتحبه بعد أبو بكر، قال له رسول الله ﷺ: عُمَرُ، فَعَدَّ رِجَالًا،\nيعني رسول الله ﷺ قال له إللي بيحبه بعد أبو بكر هو عمر بن الخطاب رضي الله عنه، وبعد عمر قعد يعد له أسماء تانية من الصحابة، فهنا عمرو رضي الله عنه سكت عشان خاف أحسن رسول الله ﷺ يذكره آخر واحد\nقال عمرو:\n\"فَسَكَتُّ مَخَافَةَ أَنْ يَجْعَلَنِي فِي آخِرِهِمْ\"\nرسول الله ﷺ شاف ذكاء عمرو وعبقريته واجتهاده وبقى له مكانة بين المسلمين،\nعشان كده رسول الله ﷺ هيرسله في مهمة تانية عظيمة جدا وهي مهمة السفارة إلى دولة عُمَان عشان يدعوهم للإسلام،\nلكن المهمة دي لسه هتحصل في شهر ذي القعدة، فنتكلم عنها لما نوصل لأحداث شهر ذي القعدة من السنة الثامنة للهجرة\nاحنا لسه في جمادى الآخرة وفي أحداث عظيمة هتحصل خلال الكم شهر الجايين دول\nعندنا بقى نقطتين المفروض إننا كنا نشرحهم المرة إللي فاتت لكن الجزء كان خلاص خلص فأجلتهم لجزء النهاردة\n◇النقطة الأولى:\nعندنا سؤال: \nلما عمرو بن العاص رضي الله عنه تَيمم بدل ما يغتسل مع وجود الماء لأنه كان خايف على نفسه من الهلاك ورسول الله ﷺ أَقَرّه على إللي عمله ده، هل احنا كمان ممكن نعمل زيه لو خُفنا على نفسنا الهلاك\nاحنا أه ممكن نعمل زيه لو فعلا ممكن نهلك لو اغتسلنا بالماء البارد في ليلة شديدة البرودة في الصحراء\nلكن احنا الوضع في زماننا دلوقتي مختلف، عندنا سخان بيسخن المية وعندنا بوتاجاز نقدر نسخن عليه مية، عندنا غلاية مية ممكن نسخن بيها مية، وهكذا،\nوطبعا الكلام عن الغُسل فما بالكم بقى بالوضوء إللي هو أقل مشقة وعادي إننا نتوضى حتى لو المية كانت سقعة في الظروف العادية\nفخُلاصة الكلام إن التيمم هينفع لو الإنسان اتحط في موقف زي موقف عمرو رضي الله كده ومقدرش يَحصل على مية سخنة\nيعني الدنيا برد شديد والمية باردة ومفيش حاجة يسخن بيها مية وكمان في مكان شديد البرودة زي الصحراء كده،\nفلو الإنسان عارف إنه لو اغتسل ممكن يموت في الظروف إللي زي كده يبقى يتيمم زي ما عمرو بن العاص رضي الله عنه عمل، \nلكن مش عايز يتوضى أو يغتسل عشان سقعان بس ومفيش خطر على حياته يبقى يغتسل ويتوضى عادي طبعا\nوممكن كمان حالة تانية يجوز فيها التيمم مع وجود الماء وهي :\nلو الإنسان مريض مرض هيضرّه لو استعمل الماء، أو مثلا يكون عنده جُرح شديد لو جه عليه مية ممكن يقتله،\nساعتها يقدر يتيمم،\nولو في جرح يبقى يلِف الجزء إللي فيه جَرح ده بقماشة مثلا ويتيمم ويمسح على القماشة دي ويغسل باقي جسمه أو يتوضى ويغسل باقي الأعضاء،\nوحصل موقف زي كده مع واحد من الصحابة بيحكيه جابر بن عبد الله رضي الله عنه بيقول:\n\" خرَجْنا في سفَرٍ فأصابَ رجلًا منَّا حجَرٌ فشجَّهُ في رأسِهِ ثمَّ احتَلمَ\"\nيعني بيقول إنه كان مسافر مع مجموعة من أصحابه فواحد منهم اتصاب بحجر في رأسه، فرأسه اتفتحت فتحة جامدة،\nولما الرجل ده نام احتلم وبقى على جنابة فلازم يغتسل عشان يرفع عنه الجنابة عشان يقدر يصلي\nفهو مبقاش عارف يعمل إيه، فسألَ أصحابَهُ فقالَ:\nهل تَجِدونَ لي رخصةً في التَّيمُّمِ؟\nيعني هو أنا ينفع أتيمم لجرحي ده بدل ما أغسله، فقالوا له:\n\"ما نجِدُ لَكَ رُخصةً وأنتَ تقدرُ علَى الماءِ\"\nيعني في مية وانت تقدر تغتسل يبقى مينفعش تتيمم\nفالرجل سمع كلامهم فعلا واغتسل، لكنه مات\nفلما رجعوا للمدينة واتحكت قصة الرجل إللي مات ده لرسول الله ﷺ قال:\n قَتلوهُ قتلَهُمُ اللَّهُ!\nألَاَ سألوا إذْ لَم يعلَموا فإنَّما شفاءُ العيِّ السُّؤالُ؛\nإنَّما كانَ يَكْفيهِ أن يتيمَّمَ ويعْصِبَ علَى جرحِهِ خرقةً ثمَّ يمسحَ عليها ويغسِلَ سائرَ جسدِهِ\"\nيعني رسول الله ﷺ قال عن الناس دي إنهم بسبب فتواهم الغلط قتلوا الرجل، فدعا عليهم من باب الزَّجرِ والتَّهدِيد لهم،\nوقال مش كانوا يسألوا مادام هم مش عارفين حاجة، وشفاء العِيّ السؤال، يعني مفيش شفاء لداء الجهل غير إن الواحد يتعلم وميقعدش يفتي الناس بغير علم\nوبدأ بقى رسول الله ﷺ يشرح الحل الصحيح للمشكلة دي عشان لو اتكررت مع حد تاني يعمل إيه\nقال إن الرجل ده كان يكفيه إنه يتيمم، وبعدين يلف الجرح بقماشة عشان يمنع وصول الماء للجرح وبعدين يمسح على القماشة دي بالمية وبعدين يغسل باقي جسمه عادي من غير ما يجيب مية على الجرح\n☆ملحوظة:\nالحديث إللي أنا قلته وشرحته ده\n على خلاف بين العلماء في علماء قالوا إنه حديث صحيح وعلماء قالوا إنه حديث فيه ضعف،أنا قلته بس عشان أشرح لكم مسألة التيمم عشان تكون واضحة\n◇النقطة التانية بقى هي موضوع الغنائم،\nالمسلمين بعد ما بيقاتلوا أي جيش بياخدوا منه غنائم، هل الغنائم دي تعتبر سرقة\nشوفوا، \nالمسلمين بيأخذوا من الحروب غنائم سواء كانت أموال أو أسلحة أو آلات أو أمتعة أو عقارات وغيرها،\nوالحاجات إللي بياخدوها دي حلال لأن ربنا قال:\n\" فكُلُوا مما غَنِمْتُم حلالاً طيباً \"\nفالغنائم إللي المسلمين بياخدوها دي مش سرقة، ليه\n☆أولا : \nلأن السرقة هي: \n《أَخْذُ مالٍ على وجهِ الاخْتِفَاء من حِرْزِه بغيرِ حَق》\n يعني واحد مخبي فلوس في مكان معين في بيته وبعدين واحد تاني ييجي يدخل البيت وهو متخفي وياخد الفلوس المخفية دي، كده بقى اسمها سرقة\nلكن الوضع في أرض الجهاد مختلف تماما لأن الأموال في أرض المعركة نوعين :إما فَيْء وإما غنيمة، \nالفَيء يعني الأموال إللي المشركين بيهربوا ويتركوها في أرض المعركة أو استسلموا بدون معركة ولا أي عمليات عسكرية، يعني أموال أخذها المسلمين بدون اي قتال، والغنيمة هي الأموال إللي بياخدها المسلمون بقتالهم للمشركين\nففي الحالتين الأموال مش موجودة في حِرْز ولا هي مخفية فخرجت برة معنى السرقة\n☆ثانيا:\n السرقة بتكون في الأموال المعصُومة المُحترمة ، وأموال الكفار المُحاربين مش معصومة ولا محترمة، يعني أموال لها حُرمة، والمُحارب أمواله لا هي معصومة ولا لها حُرْمة،\nفخرجت برده برة معنى السرقة\nوبكده نفهم إن كل الأموال إللي بيحصل عليها المجاهدون في حربهم مع الكفار تُسمى شرعاً ( غنيمة ) و ( فـيئا) وهي حلال.\n¤وفي هنا ملحوظة وهي: إن الغنائم لما بتتقسم بيكون خُمُسها لله ورسوله،\nيعني رسول الله ﷺ بياخد نصيب من الغنائم عشان يصرف بيها على نفسه وعلى بيوته، ونصيب تاني يصرفه على مصالح المسلمين العامة، يعني ده كان مصدر دَخْل رسول الله ﷺ، \nورسول الله ﷺ كان قبل الإسلام بيشتغل في الرعي وهو في بداية عمره وبياخد عليه أجر، وبعدين اشتغل بالتجارة،\nوبعدين لما جاء الإسلام السيدة خديجة سخّرت مالها لخدمة رسول الله ﷺ وخدمة الإسلام وتفرغ رسول الله ﷺ للدعوة،\nولما بقى في غنائم بقى خمس الغنائم لله ورسوله ﷺ زي ما قلنا، وكان رسول الله ﷺ بياخد من الغنائم نصيبه ويصرف منها، \nوعلى فكرة يا جماعة أيام رسول الله ﷺ مكنش الناس بياكلوا ثلاثة مرات في اليوم زي في زماننا دلوقتي\nهم وجبتين بس، وجبة في أول النهار وكانوا بيسموها الغداء، ووجبة في آخر اليوم وبيسموها العشاء،\nوكان يعدي الشهر والشهرين والتلاتة ومفيش نار للطبخ بتُقاد في أي بيت من بيوت رسول الله ﷺ،\nوكانوا عايشين على الماء والتمر، وكان ساعات الصحابة يهدوه هدايا من الطعام، يعني حد يهديه لبن، أو حد يهديه لحم أو حد يهديه تمر، كده يعني\nفرسول الله ﷺ والصحابة مكنوش بيهتموا بالأكل زي الناس دلوقتي، يعني رسول الله ﷺ يقول:\n\" بحسبِ ابنِ آدمَ أُكُلاتٌ يُقِمنَ صُلبَهُ\" \nيعني ياكل الأكل إللي يكفيه ويساعده على الحركة من غير ما يملأ بطنه ويكون الأكل هو شغله الشاغل\nومع ذلك كان في مواقف تانية كان الصحابة ورسول الله ﷺ بياكلوا فيها لحد ما يشبعوا، لكن دي كانت بتبقى حالات بسيطة، مش إن عادتهم إنهم دايما بياكلوا لحد ما يشبعوا\nوبما إننا بقى عرفنا رسول الله ﷺ كان بيصرف منين وأكله كان إيه خلونا نشوف رسول الله ﷺ كان بيقضي يومه إزاي، أو يعني زي ما بنقول كده كان إيه روتينه اليومي من أول ما يصحى لحد ما ينام\nكان رسول الله ﷺ إذا أصبح يصلي الصبح مع الصحابة في المسجد، وبعدين يفضل قاعد في مُصلاه يذكر الله لحد الشمس ما تطلع، \nوبعدين كان يصلي الضّحى إما أربع ركعات أو ساعات يزوّد عن أربعة لحد ثمانية ركعات على الراجح،\nوكان الصحابة بيقعدوا معاه فإما هو يُحدثهم من أحاديثه عن الآخرة أو عن قصص بني إسرائيل أو الصحابة نفسهم يتحدثوا ويذكروا أحداث من أيام الجاهلية ويضحكوا وكان رسول الله ﷺ يسمع كلامهم ويتبسم ﷺ،\nولما يرجع لبيته بيبقى في مهنة أهله، يعني يَحْلب الشاة، ويخيط ثوبه ويُصلح نعله إذا كان محتاج للإصلاح والخياطة،\nيعني هو كان بشر من البشر ﷺ ومكنش بيترفّع عن مساعدة نسائه في أعمال البيت،\nفإذا جاء وقت الصلاة خرج إلى الصلاة وصلى بالناس، وبعدين يقعد معاهم ويتكلم معاهم ويعلمهم ويوعظهم ويذكّرهم بالآخرة ويستمع لشكواهم ويُصلح بينهم، وبعد ما يخلص كل ده يرجع لبيته،\nوزي ما قلنا كان معظم أكل رسول الله ﷺ هو الماء والتمر، أو إذا أهدى له أحد هدية كان يأكل منها،\nورسول الله ﷺ مكنش بيَعِيب الطعام أبدا، لا بيقول ده حلو ولا ده وحش، لو الأكل عجبه بياكل، معجبوش خلاص بيسيبه من غير ما يتكلم\nولو لقى أكل بياكل ولو ملقاش بينوي الصيام ويصوم،\nيعني في مرة جاء للسيدة عائشة وسألها :\n\"هلْ عِنْدَكُمْ شيءٌ؟\"\nيعني في حاجة أكلها، فقالت له السيدة عائشة:\n\"ما عِنْدَنَا شيءٌ\"\nيعني ما عندناش حاجة، فقال لها رسول الله ﷺ:\nفإنِّي صَائِمٌ، يعني أنا خلاص صايم النهاردة وخرج رسول الله ﷺ من عندها،\n◇ده صيام تطوع يا جماعة، يعني الواحد ممكن ينوي الصيام عادي مادام مأكلش حاجة ولا شرب في أي وقت قبل الظهر،\nبعد الظهر مينفعش ينوي الصيام لازم قبل الظهر،\nاما بقى صيام فريضة زي رمضان كده لازم نبيّت النية، يعني من قبلها بيوم بالليل كده نبقى ناويين إننا هنصوم بكرة\nبعد ما خرج في حد جاء لبيت السيدة عائشة وجاب لهم طعام هدية، وهو الحَيْس، \nوالحَيْس معناه: تمر مخلوط بسمن وأَقِط، والأَقِط منتج من منتجات الألبان المجففة،\nالمهم يعني هي أكلة كده كان رسول الله ﷺ بيحبها\nفلما جاء رسول الله ﷺ قالت السيدة عائشة إن في حد جاء وزارهم وأهداهم حَيْس هدية، فقال لها رسول الله ﷺ:\n\"هاتيه\" فأكل منه رسول الله ﷺ بعد ما كان صائم.\nيعني رسول الله ﷺ كان صائم صيام تطوع وبعدين فطر عادي من غير ما يكمل صيامه،\nفلما أكل رسول الله ﷺ قال :\n\" إنَّما مَثلُ صومِ المتطوِّعِ مثلُ الرَّجلِ يُخرِجُ من مالِهِ الصَّدقةَ، فإن شاءَ أمضاها، وإن شاءَ حبسَها\"\nيعني رسول الله ﷺ بيقول إن صيام التطوع ده عامل زي الصدقة إللي الإنسان بيطلعها، فإما إنه يتصدق بالصدقة دي أو إنه ميطلعهاش لأي سبب من الاسباب،\nيعني مفيش أي حرمانية ولا حرج إن الإنسان يبقى صايم وبعدين يفطر عادي ما دام تطوّع\nنكمل باقي اليوم بتاع رسول الله ﷺ،\nساعات رسول الله ﷺ بيبقى عايز يجمع الناس لأمر مهم، فكان بيأمر حد يجمعهم أو هو بنفسه ينادي فيهم:\n \" الصلاة جامعة \"\nفلما يجتمعوا كان يقول لهم على السبب إللي جمعهم له، سواء بقى إنه يبعث بعثا، يعني يخرج جيش،\nأو نزل حكم شرعي وعايز يقوله لهم، أو إنه عايز يُخبرهم بأحداث هتحصل زي أحداث علامات الساعة ويوم القيامة، وهكذا،\nوفي وسط النهار يعني بعد الظهر كده كان ﷺ ينام القيلولة عشان يستعين بيها على قيام الليل يعني حوالي نص ساعة كده، لأن القيلولة للي بيقيم الليل زي السحور للصائم بيساعده على الصيام\nوكان رسول الله ﷺ بيطمن على أحوال المسلمين ويشوف حياتهم ماشية كويس ولّا لأ، ويطمن على معاملاتهم مع بعض، ويشوف أحوالهم في السوق، وكان بيروح للناس في مجالسهم ويتكلم معاهم،\nوكان يزور المريض ويُلبّي دعوة من يدعوه لشيء ويمشي في حاجة الضعيف والمسكين،\nيعني كان عامة يومه فيما أهمه من أمر الدين وأمور المسلمين ، سواء بقى دعوة أو نُصح أو تذكير أو تشريع أو جهاد أو أمر بمعروف ونهي عن منكر أو إعانة محتاج،\nبجد حياة تشرح الصدر، يعني اليوم كله طاعة، الواحد مجرد بس ما بيقرأ الكلام صدره انشرح \nكان بقى لما ييجي الليل ويصلى بالناس العشاء، لو كان في حاجة مهمة من أمور المسلمين كان بينشغل بيها مع كبار أصحابه، لو مفيش كان يَسْمر مع أهله شيئا،\nيعني زوجاته كل يوم يجتمعن في بيت إللي رسول الله ﷺ هيبات عندها، ويقعدوا كلهم مع بعض ويأكل معهن رسول الله ﷺ ويتكلم معهن، وبعدين كل واحدة ترجع لبيتها ويبيت عند إللي عليها الدور\n☆بالمناسبة يا جماعة،\nكل زوجة من زوجات رسول الله ﷺ كان لها حجرة خاصة بها، وأول ما جاء رسول الله ﷺ للمدينة بنى حجرتين بجانب المسجد النبوي، حجرة للسيدة سَوْدة وحجرة تانية للسيدة عائشة،\nوكان كل ما يتزوج كان يبني حجرة للزوجة إللي تزوجها، فدلوقتي رسول الله ﷺ عنده تسع حجرات لزوجاته التسعة أمهات المؤمنين رضي الله عنهن،\n وكانت الحجرات دي جنب بعض، وكانت مبنية من الطوب اللبن وسقفها من جريد النخل،\nوكانت الحجرة لها حوش فيه مكان للطبخ والحمام، وكان باب الحوش بيتفتح على المسجد، وهتلاقوا في التعليقات صورة بتوضح ترتيب الحجرات ومكانهم كان فين\nوفي النهاية كان رسول الله ﷺ بينام أول الليل وبعدين يقوم لصلاة الليل ، فيصلي ما شاء الله أن يصلي، ولما بلال رضي الله عنه يأذن لصلاة الصبح يصلي رسول الله ﷺ ركعتين ويخرج لصلاة الصبح ويصلي مع الصحابة، ويعيد نفس الأحداث\nحياة رسول الله ﷺ كانت بتجسّد قول ربنا:\n\" قُلْ إِنَّ صَلَاتِي وَنُسُكِي وَمَحْيَايَ وَمَمَاتِي لِلَّهِ رَبِّ الْعَالَمِينَ\"\nإن شاء الله المرة الجاية هنعرف الأحداث إللي حصلت بعد سرية ذات السلاسل"}, {"n": 185, "l": "الجزء 159 | احداث السنه الثامنه من الهجرة | نقض قريش لصلح الحديبيه", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الجزء_مائة_وتسعة_وخمسون\n#أحداث_السنة_الثامنة_من_الهجرة\n#نقض_قريش_لصلح_الحديبية\nإن شاء الله هنكمل الأحداث الخارجية إللي في السنة الثامنة  من الهجرة بعد سرية ذات السلاسل،\nفي شهر رجب أخرج رسول الله ﷺ سرِيّة مكونة من ثلاثمائة رجل من الصحابة بقيادة أبو عبيدة عامر بن الجرّاح رضي الله عنه،\n وكان في السرية دي عمر بن الخطاب وجابر بن عبد الله رضي الله عنهما، وأعطى رسول الله ﷺ السريّة دي جِرَاب فيه تمر يعني زي شِوَال كده صغير، عشان ياكلوا منه في رحلتهم ومكنش في حاجة غيره يقدر يُعطيها لهم،\nفكان جراب التمر ده هو مَؤُونة الجيش كله فكان أبو عبيدة بيوَزّع منه على الجيش ولما خلص ومبقاش في تَمر ولا حاجة ياكلوها طلب من إللي معاهم تمر باقي يجمّعوه كله عشان يُعيد توزيعه على الجيش،\nفجمعوا التمر كله إللي باقي معاهم وأعطوه لأبي عبيدة،\nوده بيورينا أد إيه الصحابة كانوا متعاونين مع بعض وخصوصا في وقت الأزمات،\nومحدش منهم اعترض على أبي عبيدة مثلا وقال:\n التمر إللي معايا ده بتاعي أنا، أديهولك ليه \nولّا أنا آكل منين لو أنا إديتك التمر إللي معايا، وده نصيبي وده حقي، ولّا غيرها وغيرها من الكلمات إللي بتعبر عن الأنانية وحب النفس\nفي وقت العُسرة والأزمة بنلاقيهم كلهم واقفين جنب بعض وبيساعدوا بعض بكل حب في الله\nبعد ما أبو عبيدة جمع التمر كله بقى يوزعه عليهم بالتساوي، فكان رضي الله عنه بيُعطيهم تمرةً تمرة، فكان الصحابة \nبيفضلوا يمُصّوا التمرة طول اليوم ويشربوا عليها المية عشان تكفيهم لحد الليل،\nالواحد ممكن ييجي في باله طيب وهي التمرة تعمل إيه أصلا ولّا تشبع مين\nوفعلا واحد من إللي سمعوا حكاية التمرة دي سأل جابر بن عبد الله إللي كان حاضر السريّة دي السؤال ده وقاله وهي التمرة تفيد في إيه،\nفرد عليه جابر وقال له:\n\"لقد وَجْدَنا فَقْدَها حِينَ فَنِيَت\"\nيعني التمرة إللي انت شايفها قليلة دي عرفنا قيمتها لما خلصت، وعرفنا إنها كانت فارقة معانا،\nوالتمر إللي كان مع الصحابة خلص فأصابهم جوع شديد، فأكلوا الخَبَط وهو ورق الشجر، يعني كانوا بيبِلّوا ورق الشجر في المية وياكلوه، عشان كده السرية دي اتسمت بسرِيّة الخَبَط\nسبحان الله، يعني حتى مع الشدة إللي الصحابة كانوا فيها دي لم يتركوا الجهاد في سبيل الله\nرسول الله ﷺ كان أرسل السرية دي إلي حَيّ من قبيلة جُهَينة، يعني منطقة معينة من قبيلة جهينة قريبة من ساحل البحر،\nوالهدف من السرية دي هو الدعوة إلى الإسلام بصفة عامة وكمان إظهار قوة ومَنَعة المسلمين قصاد قبيلة جهينة عشان تبقى على الحِياد ومتتحالفش مع قريش مثلا في المستقبل ضد المسلمين،\nلأن قبيلة جُهَينة قبيلة قوية فلو اتحالفت مع قريش في المستقبل ممكن يبقى في خطر على المسلمين،\nلكن لما يشوفوا قوة المسلمين هيفكروا ألف مرة قبل ما يتحالفوا مع أي عدو ضدهم،\nفخُلاصة الكلام إن السرية دي مكنش هدفها القتال زي معظم السرايا إللي خرجت قبل كده \nوفعلا محصلش أي قتال في السرية دي، لما وصلوا لساحل البحر شافوا حوت حجمه زي الجبل الصغير، وكلمة حوت اسم بيُطلق على جميع السمك، \nولو تفتكروا في قصة موسى والخضر الفتى إللي كان مع موسى قال عن السمكة إللي كانت معاهم حوت\n\"قَالَ أَرَأَيْتَ إِذْ أَوَيْنَا إِلَى الصَّخْرَةِ فَإِنِّي نَسِيتُ الْحُوتَ\"\nلكن هنا قالوا إنهم شافوا حوت عامل زي الجبل الصغير، يعني شافوا سمكة كبيرة جدا عاملة زي الجبل الصغير موجود على الشاطيء ميتة،\n☆شوفتم إزاي سبحان الله ربنا أخرج للصحابة من البحر رزق ياكلوه لأنهم كانوا في طاعة وهي الجهاد في سبيل الله،\nوهم كانوا في فقر وشدة ومع ذلك استمروا في طاعتهم على الرغم من كل ده، فكانت النتيجة إن ربنا أكرمهم بالكرامة دي،\n\"وَمَنْ يَتَّقِ اللهَ يَجْعَلْ لَهُ مَخْرَجاً ۩  وَيَرْزُقْهُ مِنْ حَيْثُ لاَيَحْتَسِبُ\"\nلما لقوا الحوت ده قال أبو عبيدة: هذه مَيتة، يعني احنا مينفعش ناكل الميتة، وبعدين فكر مرة تانية وتراجع عن كلامه وقال:\n\" أنتم رُسُل رسول الله ﷺ وفي سبيل الله\"\nيعني مفيش مشكلة إننا ناكل منه لأننا مضطرين ومفيش حاجة ناكلها، وهم كانوا قعدوا فترة طويلة ياكلوا ورق الشجر لدرجة إن حصلّهم قُرَح في أفواههم،\nفالحوت ده كان بالنسبة لهم كنز \nفقعدوا ياكلوا منه حوالي نص شهر أو ثمانية عشر يوما وهم ثلاثمائة رجل، تخيلوا بقى حجمه أد إيه،\nحتى أبو عبيدة رضي الله عنه كان عايز يقيس حجم الحوت ده، فخلى ثلاثة عشر رجلا من الصحابة يقعدوا في جوف عين الحوت، يعني في حفرة العين إللي في الوجه،\nفتخيلوا حجم باقي الحوت أد إيه لما بس العين قعد فيها ثلاثة عشر رجلا\nفأخذوا من الحوت ده اللحم والدهن وأكلوا وحملوا منه كمان معاهم للمدينة بعد ما جففوا لحمه، يعني عملوه لحم مُقَدّد\nفلما رجعوا للمدينة كانوا عايزين يعرفوا إللي عملوه ده كان صحيح ولّا لأ، فرسول الله ﷺ قال لهم:\n\" هو رزق أخرجه الله لكم، أطعمونا إن كان معكم\"\nيعني رسول الله ﷺ طلب منهم إنهم يعطوه جزء من الحوت عشان ياكل منه، \nفهو ﷺ بيقول لهم بطريقة عملية إن إللي عملوه ده كان صح وإن الحوت الميت ده حلال أكله حتى لو مكنوش في مَوضع اضطرار\nفاحنا هنا يهمنا نعرف إن يجوز أكل السمك الطافي، \nيعني لو الواحد فينا لقى على شاطئ البحر سمكة ميتة ماتت لوحدها مش هو إللي اصطادها يبقى حلال إنه ياكلها وهي كده كده هتموت لما تخرج من البحر،\nقال رسول الله ﷺ:\n\"أُحِلّت لنا مَيْتَتَان: الحوت والجَراد\"\n بس طبعا بشرط إن السمكة الطافي ده ميكنش اتغير وتعَفّن؛ لأنه لو اتغير وتعفن هيضر الجسم وبالتالي بقى لا يجوز أكله\nوبكده انتهت سرية الخَبَط أو سرية سِيفُ البحر،\nوسِيفُ البحر يعني ساحل البحر، نسبة لساحل البحر إللي لقوا عنده الحوت،\nويُقال إن السرية دي كانت قبل صلح الحديبية سنة ست للهجرة، فزمن السرية دي مش معروف بالضبط كان امتى\nفي شهر شعبان من السنة الثامنة للهجرة جهّز رسول الله ﷺ سرِيّة تانية مكونة من خمسة عشر رجلا من الصحابة بقيادة أبو قتادة الأنصاري إللي قال عنه رسول الله ﷺ خير فُرسَاننا أبو قتادة،\nاتكلمنا عنه في في الجزء مائة وواحد ممكن ترجعوا وتشوفوا قصته\nكانت مهمة السّريّة دي مواجهة قبيلة غطفان تاني\nلأن قبيلة غطفان كانت جمعت جيش في أرض نَجْد بجزيرة العرب في منطقة اسمها 《 خَضِرَة》عشان يهجم على المدينة،\nوكمان كان من مهمة السرية إظهار المَنَعة قصاد الأعراب والمشركين إللي كان مضايقهم السرايا الناجحة إللي كان رسول الله ﷺ بيرسلها وترجع منتصرة للمدينة،\nفكانوا مستنيين أي فرصة عشان يهجموا على المدينة، \nفجاءت السرية دي عشان يوقفوهم عند حدهم زي ما بيقولوا ويوروهم بالواقع العملي إننا أقوياء ومش خايفين منكم ولو فكرتكم تهجموا على المدينة مش هنرحمكم\nخرج أبوقتادة من المدينة وكعادة السرايا إللي بيرسلها رسول الله ﷺ ضد القبائل كانت السريّة بتسير في اليل، وتكمُن في النهار، \nوصلت السرية لمكان تجمع الجيش وهجموا عليهم فجأة فهرب جيش المشركين من الخمسة عشر رجل وأخذ المسلمون منهم غنائم وسبايا كتير ورجعوا للمدينة\nفي شهر شعبان برده حصلت حادثة في مكة هتكون سبب في أحداث كبيرة جدا بعدين\nإيه إللي حصل\nواحد من بني بَكْر اعتدى على واحد من بني خُزَاعة داخل الحرم\nواحدة واحدة كده وبراحة\nفي صلح الحديبية: الشرط الرابع لو تفتكروا بيقول :\nإن إللي عايز يدخل في حِلف المسلمين من القبائل يدخل، وإللي عايز يدخل في حِلف قريش يدخل، \nوالقبيلة إللي هتدخل مع أي طرف بقت خلاص جزء من الفريق ده، لو تعدّى عليها أي حد بقى الاعتداء على الطرف الأساسي في المعاهدة،\nوقلنا إن قبيلة خزاعة دخلت مع المسلمين وبني بكر دخلوا مع قريش، فلو قريش أو بني بَكر اعتدوا على خُزاعة يبقى كأنهم بالضبط اعتدوا على المسلمين ويبقى المعاهدة اتنقضت خلاص،\nوهو ده إللي حصل بالضبط\nالمفروض إن قريش بتأَمّن أي حد يدخل الحرم ومفيش قتال عند الكعبة ولا الكلام ده،\nبنو بكر كان دايما في بينهم وبين خزاعة حروب وقتال من أيام الجاهلية، فلما جاء الإسلام انشغلوا بيه عن الحروب إللي كانت بينهم،\nفلما حصلت الهدنة بين خزاعة وبني بكر في صلح الحديبية، بني خزاعة بقوا حاسين بالأمان أكتر ومتوقعوش إن بني بكر ممكن يهجموا عليهم،\nفمجموعة من بني بكر بقيادة واحد اسمه نَوْفَل بن معاوية الدَّيْلِي هجموا في الليل على مجموعة من خزاعة بسبب ثأر كان بينهم وقعدوا يقاتلوا بعض واستعانت المجموعة دي من بني بكر بقريش، فساعدهم ناس من قريش في قتل المجموعة دي من خزاعة حليفة رسول الله ﷺ،\nويُقال في بعض الروايات إن إللي ساعدوا بني بكر من قريش هم صفوان بن أمية وعكرمة بن أبي جهل وسهيل بن عمرو إللي كتب الصلح وعمل مشكلة عشان يرجع أبو جندل والصلح مكنش لسه اتكتب أصلا، وهو نفسه إللي نقض العهد سبحان الله\nفده كده نقض واااضح لصلح الحديبية \nياريتهم بقى اكتفوا بالاعتداء عليهم، ده المجموعة دي من خزاعة دخلوا منطقة الحرم عشان ينقذوا نفسهم لأنهم عارفين إن محدش بيُقاتِل في الحرم، \nفراح داخل وراهم نَوْفَل بن معاوية عشان يقتلهم، فجاء وراءه المجموعة إللي معاه من بني بكر فقالوا له:\n\" يا نَوْفَل إنا قد دخلنا الحرم  إلهك . إلهك\"\nيعني احنا خلاص دخلنا الحرم، قوانين إلهك، قوانين اللات والعزى وهُبل وغيرها لم تُشرّع القتال في داخل البيت الحرام،\nفقال لهم كلمة شديدة جدا:\n\" لا إِلهَ اليوم! إنكم لتسرقون في الحرم، أفلا تُصيبون ثأركم فيه؟\"\nيعني انتم بتضحكوا على نفسكم، إله إيه إللي بتتكلموا عنه\n ده انتم بتسرقوا في الحرم مش هتاخدكم بثأركم في الحرم\nوشجعهم فعلا على قتل المجموعة دي من بني خزاعة، وقتلوا منهم حوالي من عشرين لثلاثة وعشرين رجل وكان في المجموعة إللي قُتلت دي مسلمين ومشركين،\nواحد من بني خزاعة دول اسمه عمرو بن سالم عرف يهرب منهم وتوجه للمدينة عند رسول الله ﷺ،\nأول ما وصل للمدينة وقف وسط المسلمين وأمام رسول الله ﷺ وبدأ يحكي إللي حصل معاه هو وإللي كانوا معاه في أبيات شعرية،\nلما سمع رسول الله ﷺ كلام عمرو بن سالم قال له:\n\" نُصرتَ يا عمرو بن سالم\"\nيعني متخفش أنا هجيب لك حقك\nإزاي رسول الله ﷺ هينصر عمرو بن سالم، ويا ترى قريش هتعمل إيه في الورطة إللي حطوا نفسهم فيها دي،\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 186, "l": "الجزء 160 | احداث السنه الثامنه من الهجرة | قرار فتح مكه", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وستون\n#أحداث_السنة_الثامنة_من_الهجرة\n#قرار_فتح_مكة\nاتكلمنا المرة إللي فاتت عن قريش لما ساعدت بني بَكر في الهجوم على خُزاعة ونَقْضِهم الصريح لصلح الحُدَيبيَة،\nوشوفنا إن عمرو بن سالم استطاع إنه يهرب من مكة ويروح المدينة ويحكي لرسول الله ﷺ إللي حصل ورسول الله ﷺ رد عليه وقال له إنه هينصره،\nبعد ما جاء عمرو بن سالم وحكى إللي حصل جاء لرسول الله ﷺ من مكة بُدَيْل بن وَرقَاء عشان يشتكي لرسول الله ﷺ هو كمان ويطلب منه إنه يجيب له حقه وحق قبيلته إللي اتغدر بيها،\nوبُديل كان من خُزَاعة وله بيت في مكة، فكان في بيته إللي في مكة ده وقت ما حصل الاعتداء من بني بكر على المجموعة بني خزاعة،\nفبعض الأشخاص من بني خزاعة إللي حصل عليهم الاعتداء عرفوا يهرب ويروحوا لبُدَيل في بيته ويستنجدوا بيه وحكوا له إللي حصل،\nوبُدَيْل ده لو تفتكروا كان من الناس إللي قريش أرسلتهم لرسول الله ﷺ كوسيط لما كان جاي مكة للعمرة قبل صُلح الحديبية عشان يعمل مفاوضات مع رسول الله ﷺ،\nيعني بُديل بن ورقاء صديق لقريش، ومش بس كده ده كان ساعتها لسه مشرك ومَصالح بُديل كلها من تجارة وغيرها في داخل مكة المكرمة، وكمان بُدَيل كان صديق شخصي لأبي سفيان إللي كان ساعتها زعيم مكة،\nيعني كان المفروض يروح لأبي سفيان عشان يحل له الموضوع\nلكن بُديل مرحش لأبي سفيان واستنجد بيه وقال له قبيلتك والمتحالفين معاهم قتلوا ناس من قبيلتي وادفع لنا ديّات القتلى بتوعنا،\nبُديل ساب الناس كلها وراح لرسول الله ﷺ عشان عارف إن مفيش حق بيضيع عند رسول الله ﷺ، أيوة الحقوق ممكن تضيع عند قريش وعند المشركين لكن عند رسول الله ﷺ كل واحد بياخد حقه بالعدل\nقبل ما نعرف رد فعل رسول الله ﷺ وإيه الموقف إللي أخذه، خلونا نشوف قريش هتعمل إيه في الورطة إللي هم فيها دي\nقريش عملت مجلس للتشاور بينهم بقيادة أبو سفيان زعيم مكة وحضر المجلس ده عكرمة بن أبي جهل وصفوان بن أمية وسُهيل بن عمرو وغيرهم من رجال مكة وزعمائها،\nقعدوا مع بعض وبدأوا يفكروا بقى هيحلوا المشكلة دي إزاي،\nوطبعا وهم بيفكروا حاطين في اعتبارهم وضع المسلمين دلوقتي وخصوصا أبو سفيان\nيعني الوضع وصل بيهم لحد الانبهار بالمسلمين، يعني الناس المستضعفين إللي خرجوا مطاردين وتركوا أموالهم وديارهم من ثماني سنوات دلوقتي انتصروا على اليهود في خيبر، وملك الروم هرقل نفسه خايف من المسلمين بعد الحوار إللي حصل بينه وبين أبو سفيان واتكلمنا عنه قبل كده،\nده غير انتصار المسلمين في مؤتة على المائتين ألف مقاتل من الروم والغساسنة،\nوكمان دخول بعض الدول المحيطة بمكة للإسلام، زي البحرين واليمن،\nوضيفوا للكلام ده كله دخول رسول الله ﷺ لمكة في عمرة القضاء وحرص رسول الله ﷺ على إظهار قوة المسلمين أمام قريش وإللي فعلا سابت عندهم أثر كبير جدا في نفوسهم\nفكل ده بقى مخلي عندهم خوف ورهبة من مواجهة المسلمين،\nده غير كمان إنهم لقوا نفسهم مستفادوش أي حاجة من مساعدتهم لبني بكر في الاعتداء على قبيلة خزاعة، بالعكس ده المساعدة دي هتضرهم أهه \nوهم بيتشاوروا وبيفكروا شافوا إن احتمال وقوع حرب بينهم وبين المسلمين احتمال وارد، هو أه صعب يتصوروا الاحتمال ده، لكنه احتمال واحتمال كبير كمان وهم مش أد الاحتمال ده\nفملقوش قصادهم غير حل واحد وهو:\nالذهاب إلى المدينة عشان يستسمحوا رسول الله ﷺ في إنه يتغاضى عن الخطأ إللي حصل ده ويكبر دماغه وخلاص يعديها ويزودوا كمان الهدنة إللي بينهم\nوفعلا أخدوا القرار بإنهم يرسلوا لرسول الله ﷺ واحد منهم عشان يستسمحه، والقرار ده يعتبر أصعب قرار أخدته قريش لأنه فيه تنازل كبير جدا من قريش،\nلأ ومش بس كده ده كمان اختاروا أبو سفيان عشان هو إللي يروح يكلم رسول الله ﷺ \nأبو سفيان زعيم مكة كلها وزعيم بني أمية وإللي بينه وبين المسلمين حروب... غزوة أُحد والأحزاب وهجومه على المدينة يعني ده مش أي حد\nفعلا سبحان الله المُعزّ المُذِل\nتجهّز أبو سفيان وخرج من مكة للمدينة عشان يقابل رسول الله ﷺ ويستسمحه في إللي حصل ويطلب منه يزوّد العهد إللي بينه وبين مكة،\nعلى ما يوصل بقى أبو سفيان للمدينة خلونا نرجع لرسول الله ﷺ ونشوف هو ناوي على إيه مع قريش بعد ما نقضوا العهد\nنَقْض العهد إللي حصل ده يُعتبر أزمة كبيرة جدا، والإنسان الناجح بيعرف يحوّل الأزمة لفرصة يطلع منها بمكاسب لصالحه أو على الأقل يطلع بأقل الخسائر الممكنة،\nوهو ده إللي رسول الله ﷺ كان عايز يعمله\nإزاي يخرُج من أزمة نقض الصلح ومقتل أعداد من المسلمين والمشركين ظلما في أرض الحرم بفائدة للإسلام والمسلمين\nخلونا نفكر مع رسول الله ﷺ ونشوف وضع المسلمين في الجزيرة العربية في الوقت الحالي ووضع قريش\n◇أولاً: الوضع السياسي والعسكري للمسلمين:\n الوضع السياسي والعسكري للمسلمين بعد غزوة مؤتة وذات السلاسل وضع ممتاز جدا، وأعداد المسلمين بتزيد، \nوالجيش الإسلامي متدرب تدريب كويس جدا في معارك حقيقية على مدار سبع سنين مع اليهود والمشركين وكمان مع الرومان زي ما شوفنا إللي حصل في مؤتة ومحقق انتصارات كتيرة،\nفبالتالي معنويات المسلمين عالية جدا،\nده غير إن سُمعة المسلمين طيبة على مستوى الجزيرة كلها وعلى مستوى العالم بشهادة هرقل،\nوالدولة الإسلامية لها علاقات قوية جداً مع أكثر من مملكة من ممالك الأرض، فاليمن دولة مسلمة، والبحرين دولة مسلمة، وفي علاقات مع الحبشة ومع مصر،\nوكمان حصل تناقص في أعداء الإسلام، يعني اليهود خلاص خلصنا منهم، ومعظم القبائل العربية إما مهزومة من المسلمين أو بينهم وبين المسلمين عهد، حتى قبيلة غطفان إللي دايما عاملة قلق مع المسلمين أرسل لهم رسول الله ﷺ آخر سرية زي ما حكينا المرة إللي فاتت فمفيش منهم خطر دلوقتي،\nومش بس كده ده هييجوا كمان يشاركوا المسلمين في فتح مكة زي ما هنشوف إن شاء الله\n◇ثانيا: الوضع العسكري لقريش\n الوضع العسكري لقريش كان ضعيف، وبيزيد ضعف مع مرور الوقت،\nورسول الله ﷺ نفسه قال بعد هزيمة قريش في الأحزاب :\n\" الآن نغزوهم ولا يغزونا\"\nفرسول الله ﷺ كان شايف إن الدولة الإسلامية كل يوم في عُلُو واضح وقريش في هبوط واضح،\nومننساش طبعا دخول خالد بن الوليد وعمرو بن العاص وعثمان بن طلحة في الإسلام، دول لوحدهم ضربة جامدة لقريش في الناحية العسكرية\nده غير إن مبقاش لهم حلفاء غير بني بكر تقريبا، وحتى بني بكر كان في بينهم وبين قريش خلافات والعلاقة بينهم مش جامدة أوي يعني، \nفتقدروا تقولوا إن قريش دلوقتي واقفة بطولها قصاد المسلمين وحلفاءهم وقوتهم\nيعني باختصار كده وضع الدولة الإسلامية مستقر جداً وفي الناحية التانية قريش وضعها ضعيف جدا وغير مستقر\n◇ثالثا: الوضع القانوني والشرعي للمسلمين.\nبمعنى إن بعد نقض قريش المعاهدة بقتل أبرياء وكمان داخل الحرم  محدش هيقدر يُنكر على المسلمين لو المسلمين أخدوا قرار الحرب وفتح مكة، لأن قريش هي إللي نقضت العهد والمسلمين دلوقتي لهم حق الرد\nوفتح مكة أصلا كان هيحصل عاجلا أم آجلا، لكن مكنش لسه في فرصة، فدلوقتي جاءت الفرصة بتدبير من عند ربنا،\nفقرر رسول الله ﷺ إنه ينتهز الفرصة دي عشان يفتح مكة\n◇رابعا:\n المسلمين عليهم واجب شرعي إنهم يساعدوا خُزاعة إللي اتظلمت دي ومينفعش يسيبوهم بدون مساعدة؛\nلأن ده إللي اتفقوا عليه معاهم في صلح الحديبية وإن أي حد يعتدي عليهم يبقى كده اعتدى على المسلمين ويجب على المسلمين إنهم يدافعوا عنهم، وزي ما  قال رسول الله ﷺ :\n\"الْمُسْلِمُونَ عَلَى شُرُوطِهِمْ\"\nوفي نفس الوقت الدفاع عن خُزاعة واجب سياسي مهم جدا، لأن ده تعدي على كرامة الدولة الإسلامية لأن الناس إللي اتقتلت دي حُلفَاء المسلمين فمعنى الاعتداء ده إنهم مش عاملين حساب للمسلمين ومش معترفين بيهم،\nومش بس كده ده كمان كان في مسلمين وسط القتلى،\nفلازم وقفة قوية ضد إللي حصل ده\nفكانت النتيجة إللي توصّل لها رسول الله ﷺ إنه أخذ القرار بفتح مكة، والقرار ده مكنش سهل على فكرة\nده كان من أصعب القرارات؛\nلأن مكة مش زي أي بلد، مكة دي عُقر دار قريش ولها تاريخ طويل، وقريش مش قبيلة سهلة، دي أعز قبيلة في العرب، والعرب كلهم بيحترموها وبيوقّروها، \nوفي ناس كتير ممكن يغيّروا موقفهم من رسول الله ﷺ إذا شافوا إن قريش اتهددت في عقر دارها مكة إللي هي البلد الحرام،\nومكة لها مكانة كبيرة جدا في قلوب كل العرب،\nفالموضوع أه فرصة لكن في نفس الوقت مش سهل\nوعلى فكرة يا جماعة إللي ساعد رسول الله ﷺ إنه يقدر ياخد القرار بفتح مكة في الوقت ده هو 《الجاهزية التامة》،\nيعني رسول الله ﷺ كان عارف إنه هيفتح مكة في يوم من الأيام، لكن عشان يفتحها لازم يكون مستعد للحظة دي،\nيعني يبقى عنده جيش قوي الإيمان متدرب ومُنظم ومستعد للقتال في أي لحظة،\nلكن تخيلوا كده لو المسلمين مش مدربين ولا متربيين إيمانياً وعايشين حياة مُرفهة مش هاممهم غير ملذات الدنيا ومتعلقين بالدنيا؛ لو رسول الله ﷺ قالهم يلا عشان نجاهد ونفتح مكة حد فيهم هيفكر في الخروج أصلا وهو في احتمال إنه يموت\nطبعا لأ لأنهم ساعتها مش هيبقوا فاهمين يعني إيه قضية الجهاد أصلا ولا نشر الإسلام ولا تعبيد الناس لرب العالمين،\nفرسول الله ﷺ أول ما جاءت له الفرصة عرف يستغلها لأنه كان بيستعد لها بقاله سنين\nطبعا لما جاء بُديل بن ورقاء لرسول الله ﷺ كان \nأقصى أحلامه إن رسول الله ﷺ يأمر قريش إنهم يقتلوا القاتلين، أو على الأقل يدفعوا دية الناس إللي اتقتلت من خزاعة دي\nمتخيلش أبدا إن رسول الله ﷺ هيجهز جيش وهيروح يفتح مكة\n◇ممكن حد يسأل سؤال ويقول معلش يعني فرصة إيه واجتهاد إيه، هو مش رسول الله ﷺ مش بيعمل حاجة إلا بالوحي، يعني هو بينفذ إللي ربنا بيأمره وخلاص\nبراحة كده وواحدة واحدة عشان النقطة دي مهمة\nالأقوال والأفعال إللي رسول الله ﷺ بيقولها وبيعملها بتنقسم لقسمين \n☆القسم الأول: \nأقوال وأفعال صادرة بتوقِيف من الوحي و بِأَمْر من ربنا،\nيعني ربنا يقول لرسول الله ﷺ قل كذا وافعل كذا، فيكون رسول الله ﷺ فيها مُبلّغا ناقلاً أميناً،\nوالقسم ده هو الغالب على أقوال وأفعال رسول الله ﷺ\n☆القسم الثاني:\nأقوال وأفعال صادرة عن رأي رسول الله ﷺ واجتهاده، بدون ما يكون فيها رسول الله ﷺ مُبلّغا ولا ناقلا، ولكنه  مشرِّعًا مجتهدا،\nولو كان في قرار رسول الله ﷺ واجتهاده خطأ يأتي الوحي بتعديل الخطأ ده،\nلكن لو قراره صحيح إما يأتي الوحي بإقرار فعل رسول الله ﷺ أو إن ميجيش وحي أصلا ويبقى ده إقرار لفعل رسول الله ﷺ عن طريق السكوت عنه،\nيعني مثلا فاكرين قصة الزبير بن العوام وجاره الأنصاري لما اختلفوا مع بعض على مين إللي يسقي الأرض الأول، ورسول الله ﷺ حكم للزبير رضي الله عنه\nأهه ده كان من اجتهاد رسول الله ﷺ إللي سكت عنه الوحي، في حين إن رسول الله ﷺ لما اجتهد في مصير أسرى بدر وشاف إنه ياخد بدالهم الفداء وده كان اجتهاد خاطئ من رسول الله ﷺ نزل القرآن يوضح الخطأ إللي حصل ده ويقول لرسول الله ﷺ الصح كان إيه\n\" مَا كَانَ لِنَبِيٍّ أَنْ يَكُونَ لَهُ أَسْرَى حَتَّى يُثْخِنَ فِي الأرض\"\n◇وكده هيطلع لنا سؤال تاني، وهو : أمّال إيه معنى:\n \"وَمَا يَنطِقُ عَنِ الْهَوَىٰ ۩ إِنْ هُوَ إِلا وَحْيٌ يُوحَى\" \nشوفوا،\nالكفار كانوا بيقولوا إن إللي بيعلم رسول الله ﷺ القرآن بشر، فربنا أنزل الآية دي وقال لهم إن القرآن وحي من عند ربنا وإن رسول الله ﷺ مش بيجيب حاجة من عنده ولا بيعلمه بشر، ومش بيحكم ولا بيتكلم بهواه ولا بِكذب ولا بيفترى على الله، ولكنه بيحكم ويجتهد عن طريق القرآن والأمثلة إللي ربنا ضربها لرسول الله ﷺ في القرآن عن الأمم السابقة\nفلما نيجي نقول بقى إن رسول الله ﷺ شاف إن نقض قريش للعهد فرصة مناسبة رسول الله ﷺ استغلها عشان يفتح مكة نعرف إن رسول الله ﷺ اجتهد هنا زي ماحنا كبشر بنجتهد عادي جدا، ومادام الوحي مجاش يُنكر على رسول الله ﷺ اجتهاده يبقى كده اجتهاده صحيح\n♡أنا حبيت أوضح النقطة دي بالذات لأن ناس كتير جدا  فاهمة إن رسول الله ﷺ كان مجرد آلة كده مش بيفكر ولا بيجتهد وقاعد بس كده مبيعملش حاجة خالص غير لما يجيله الوحي، وده طبعا غير صحيح\nرسول الله ﷺ بيخطط وبيرتب وبيشاور الصحابة وبياخد برأيهم ويشوفوا أحسن رأي وبيعملوا بيه مادام الوحي مجاش يقول عكس رأيهم واجتهادهم\n☆طبعا تفصيل المسألة بالأدلة هتلاقوه في رابط في التعليقات من موقع الإسلام سؤال وجواب\nوصل أبو سفيان زعيم مكة للمدينة خلاص، ياترى هل هيقدر يقنع رسول الله ﷺ إنه يتغاضى عن نقض العهد وإنه يمد العهد إللي بين قريش وبين المسلمين\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 187, "l": "الجزء 161 | احداث السنه الثامنه من الهجرة | مفاوضات ابو سفيان مع رسول الله", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وواحد_وستون\n#أحداث_السنة_الثامنة_من_الهجرة\n#مفاوضات_أبو_سفيان_مع_رسول_الله\nوقفنا المرة إللي فاتت عند وصول أبو سفيان للمدينة عشان يحاول يقنع رسول الله ﷺ إنه يطوّل مدة العهد إللي بين قريش وبين المسلمين وإن رسول الله ﷺ يَتغاضى عن نَقْض قريش لصلح الحديبية،\nوقبل ما يوصل أبو سفيان للمدينة كان رسول الله ﷺ أخبر الصحابة بمجيء أبو سفيان قال للصحابة:\n\" كأنكم بـأبي سفيان قد جاءَكم يَشُدّ في العَقد ويزيد في المدة\"\nيعني أبو سفيان هييجي عشان يأَكد على الصّلح وكمان يزيد المدة، ودي طبعا معجزة لرسول الله ﷺ إنه قال لهم عن غيب لسه محصلش،\nوفعلا جاء أبو سفيان للمدينة ودخل على رسول الله ﷺ عشان يكلمه،\n☆في هنا بقى قصة مشهورة ولكنها غير صحيحة، وهي:\n《 إن أبا سفيان لما جاء للمدينة  قبل ما يدخل على رسول الله ﷺ ويكلمه راح لبنته أم حبيبة زوجة رسول الله ﷺ عشان يكلمها تتوسط له عند رسول الله ﷺ،\nفلما جه يتكلم معاها وجه يقعد على الفراش إللي موجود في الغرفة، أم حبيبة أخدت الفراش وطبقته ومنعت أبوها إنه يقعد على الفراش ده،\nفأبو سفيان استغرب وسألها\n\" يَا بُنَيَّةُ مَا أَدْرِي أَرَغِبْتِ بِي عَنْ هَذَا الْفِرَاشِ ، أَمْ رَغِبْتِ بِهِ عَنِّي؟\"\nيعني انتِ منعتيني اقعد على الفراش ده لأنك شايفة إنه لا يليق بسيد مكة يقعد عليه ويستحق أفضل من كده، ولّا الفراش هو إللي غالي عليكِ فمش عايزاني أقعد عليه، فردت عليه أم حبيبة وقالت له:\nهو فِراش رسول الله ﷺ وأنتَ مُشرك نَجِس، فلم أحبّ أن تجلس على فراشه \"\n\"ّفقال لها أبو سفيان : \"يا بُنَيّة والله لقد أصابك بعدي شَر\nوخرج من بعدها وهو غضبان وراح لرسول الله ﷺ》\nالقصة دي كلها مع إنها مشهورة وفي مشايخ بيقولوها لكنها للأسف غير صحيحة\n لأن إسنادها ضعيف وفي رواة في القصة مجهولين وكمان المتن بتاعها إللي هو القصة نفسها لا يصح وبيخالف القرآن والحديث الصحيح، إزاي\n◇أولا:\n ربنا قال في القرآن :\n\" وَإِنْ جَاهَدَاكَ عَلَى أَنْ تُشْرِكَ بِي مَا لَيْسَ لَكَ بِهِ عِلْمٌ فَلا تُطِعْهُمَا وَصَاحِبْهُمَا فِي الدُّنْيَا مَعْرُوفًا\"\nيعني المسلم يجب عليه إنه يبر أبويه حتى لو كانوا مشركين، وحتى لو دعوه للإشراك بالله فهو ميسمعش كلامهم لكن في نفس الوقت يعاملهم معاملة حسنة، \nوهنا أم حبيبة أم المؤمنين معملتش كده، بالعكس ده عاملت أبوها معاملة سيئة وأغضبته وخالفت القرآن وأم المؤمنين متعملش كده\n◇ثانيا:\n أم حبيبة رضي الله عنها لما طبّقت الفراش ومنعت أباها من إنه يجلس عليه عشان هو نجس، هيتفهم من تصرف أم حبيبة ده إن المشرك نجس نجاسة حِسِّيّة، يعني جسمه نجس وده غير صحيح لأن المشرك نجس نجاسة معنوية،\nوالنجاسة المعنوية هي نجاسة الكفر والفسوق والعصيان\n◇ثالثا:\nأم أسماء بنت أبي بكر الصديق جاءت للمدينة عشان تزور بنتها أسماء وكانت مشركة،\nفأسماء راحت سألت رسول الله ﷺ تعمل إيه مع أمها، هل تَصِلهَا وتُحْسِن إليها ولّا لأ، فقال لها رسول الله ﷺ:\n\" نعم صِلِي أمك\"\nوأسماء بنت أبي بكر أخت السيدة عائشة من أبوها، يعني أم أسماء كانت مشركة لكن أم السيدة عائشة كانت مسلمة وعايشة معاها في المدينة وكان اسمها أم رُومان،\nفهنا مُقدمة القصتين واحدة فالمفروض تكون النهاية واحدة، يعني السيدة أسماء جاءتها أمها المشركة تزورها،\nوأم حبيبة جاءها أبوها المشرك يزورها، فالمفروض إن أم حبيبة تُحسن لأبوها زي ما رسول الله ﷺ قال لأسماء،\nوإلا كده هيبقى ظاهر إن أم حبيبة تخالف هدي رسول الله ﷺ وده مستحيل لأن زوجات رسول الله ﷺ هن أكثر الناس اتباع لهَدْي رسول الله ﷺ\n《تفصيل المسألة بالأدلة والشرح هتلاقوها في رابط في التعليقات\n》\nفأبو سفيان توجه مباشرة لرسول الله ﷺ عشان يحاول معاه إنه يطوّل مدة العهد إللي بينهم،\nدخل أبو سفيان على رسول الله ﷺ وبدأ يكلمه ويقول له عن رغبته في إطالة مدة الصّلح،\nلكن رسول الله ﷺ رفض إنه يرد على أبي سفيان أصلا، يعني أبو سفيان بيتكلم ورسول الله ﷺ مبيردش عليه نهائي\nوطبعا دي مش عادة رسول الله ﷺ أبدا،\nيعني رسول الله ﷺ كان من عادته إنه بيُحسِن استقبال الضيوف ويُكرمهم\nوكان يستمع ويقبل منهم ويتحاور معهم وخاصة الزّعماء،\nلكن ده محصلش هنا مع إن أبو سفيان زعيم قريش\nليه بقى\nلأن رسول الله ﷺ عايز يفتح مكة وعايز يستغل الفرصة إللي بين إيده دلوقتي ومش عايز كلام أبي سفيان يُؤثر عليه بأي صورة من الصور\nوفي نفس الوقت رسول الله ﷺ مقلش لأبي سفيان انتم عملتم كذا وكذا، ولم يهدّده مثلا ولم يقل له كلاماً شديداً،\nكل ده عشان رسول الله ﷺ ميلفتش نظر أبي سفيان إلى إن في احتمال لفتح مكة والهجوم عليها،\nلأن رسول الله ﷺ عايز يفتح مكة بدون أي قتال، عايز مكة تستسلم له وميحصلش قتال عشان يشوفوا عظمة الإسلام والمسلمين فيكون ده دافع لهم للدخول في الإسلام،\nلأن زي ما قلنا قبل كده إن إللي يهم رسول الله ﷺ هو إدخال الناس للإسلام مش همه الانتقام ولا إنه ياخد أموالهم ويقتلهم\nأبو سفيان لما شاف إن رسول الله ﷺ لم يقبل إنه يتفاوض معاه، وإنه مردش عليه أصلا خرج من عند رسول الله ﷺ،\nوالمُتوَقع هنا من أبي سفيان إنه يرجع لمكة وهو غضبان ويجهز جيش ويهجم على المدينة عشان ينتقم لكرامته إللي اتهانت دي وتحصل أزمة بين قريش والمدينة\nلكن حصل عكس كده تماما\nخرج أبو سفيان من عند رسول الله ﷺ وتوجّه لوزير رسول الله ﷺ الأول أبو بكر الصديق رضي الله عنه وطلب منه نفس الكلام،\nيعني إنه عايز يجدد العهد ويزيد المدة فكان عايز يتوسط له عند رسول الله ﷺ لكن الصديق رضي الله عنه قال له في حَزم وقوة واضحة: \nما أنا بفاعل\nيعني أنا مش هتوسط بينك وبين رسول الله ﷺ، فخرج أبو  سفيان من عند أبي بكر وهو مصدوم الصدمة التانية\nأول صدمة لأبي سفيان كانت مع رسول الله ﷺ والثانية مع أبي بكر، ومع ذلك لم ييأس، \nاتّجه إلى الوزير الثاني لرسول الله ﷺ وهو عمر بن الخطاب رضي الله عنه عشان يتوسط له عند رسول الله ﷺ، \nوياريته ما كان راح\nأول ما راح أبو سفيان لعمر وطلب منه نفس الطلب عمر قاله بمنتهى القوة:\nأنا أشفع لكم عند رسول الله ﷺ \nوالله لو لم أجد لكم إلا الذَّر لجاهدتكم به\nيعني انت عايزني أنا اتوسط لك عند رسول الله ﷺ؟! ده أنا لو ملقتش جيش يقاتلكم غير النمل الصغير لقاتلتكم به،\nالكلام صدم أبا سفيان طبعا هو متوقعش إن عمر يرد عليه الرد ده\nخرج من عنده وهو مصدوم الصدمة الثالثة، ومع ذلك لسه مستسلمش؛ لأن وضعه ضعيف دلوقتي وعارف إنه مش هيقدر على حرب المسلمين فكان بيبذل كل مجهوده عشان يخلّي رسول الله ﷺ يرضى إنه يجدد العهد بينهم،\nفبعد ما خرج من عند عمر راح لعلي بن أبي طالب فدخل  عنده وكانت معاه زوجته فاطمة بنت رسول الله ﷺ وكان معاهم ابنهم الحسن وكان غلام صغير بيلعب وسطهم،\nفقال أبو سفيان لعلي رضي الله عنه:\nيا علي! إنك أَمسُّ القومِ بي رحماً، وإني قد جئتُ في حاجة فلا أرجعنّ كما جئتُ خائباً...اشفع لي إلى محمد\nيعني هو بيقول لعلي إنه أقرب واحد له من ناحية الرحم وصلة القرابة، وهو جاء له يطلب منه خدمة ومش عايزه يرجعه خائب من غير ما ينفذ له طلبه، فطلب منه إنه يتوسط له عند رسول الله ﷺ،\nفقال له علي: \nوَيْحك يا أبا سفيان! لقد عزم رسول الله ﷺ  على أمر ما نستطيعُ أن نكلّمَه فيه\nيعني رسول الله ﷺ لمّا سمع بخيانة بني بكر وقريش وقتلهم لرجال من خزاعة وصل لدرجة من الغضب إن مفيش حد يقدر يكلمه ومحدش عارف هو هيعمل إيه ﷺ، ودي كانت الصدمة الرابعة لأبي سفيان\nالْتَفت أبو سفيان إلى فاطمة وقال لها:\nهل لكِ أن تأمري ابنك هذا فيُجِير بين الناس فيكون سيّد العرب إلى آخر الدهر\nيعني بيطلب من السيدة فاطمة إنها تخلي الحسن وهو غلام صغير يقوم وسط الناس ويعلن حمايته لقريش وإن إللي هيتعرض لهم بسوء يبقى تعرض للحسن بسوء، ومش هننسى له الجميل ده أبدا،\nإللي هو كلام غير منطقي أصلا، طفل إيه إللي يقف وسط الناس ويقول إن قريش في حمايته\nفانتم تخيلوا المرحلة إللي وصل لها أبو سفيان عشان يطلب من غلام صغير إنه يحمي قريش\nففاطمة رضي الله عنها قالت له:\nوالله ما يَبْلغُ ابني ذاكَ أن يُجِير الناس\nوما يجيرُ أحدٌ على رسول الله \nيعني بتقوله ابني ده أصلا ميقدر يعمل إللي بتقوله ده لأنه صغير، وحتى لو يقدر فهو مش هيعمل كده من غير إذن ورضا رسول الله ﷺ،\nودي كانت الصدمة الخامسة لأبي سفيان، وساعتها الدنيا ضلّمت في وجه أبي سفيان فقال لعلي وكله يأس وقنوط:\nيا أبا الحسن إني أرى الأمور قد اشتدت عليّ، فانصحني\nفقال له عليّ:\nوالله ما أعلم لك شيئا يُغني عنك، ولكنك سيد بني كنانة فقم فَأَجِر بين الناس، ثم الْحِق بأَرضك\nيعني أنا مش لاقيلك أي حل بصراحة، لكن انت سيد بني كِنانة، فانت قُم بين الناس وقل إن قريش في حمايتك ومحدش يعتدي عليهم وبعدين ارجع لبلدك،\nفأبو سفيان اتحمس وسأل علي: \nأَوَ ترى ذلك مغنياً عني شيئاً؟!\nيعني لو أنا عملت كده هيبقى في فايدة والناس هتسمع كلامي،\nفقال له علي:\nلا والله ما أظنه، ولكني لم أجد لك غير ذلك\nيعني لو عملت كده مش هيفيدك في حاجة لكن ده الحل الوحيد إللي قصادك،\nولإن أبا سفيان كان في حالة إحباط شديدة قام فعلا في المسجد وقال:\nأيها الناس! إني قد أَجَرْتُ بين الناس\nيعني خلاص أنا فرضت حمايتي بين الناس ومفيش حد يعتدي على حد وخلاص المشكلة اتحلت،\nوركب البعير بتاعه وانطلق ناحية مكة\nإللي هو عَرْض الرّجل الواحد one man show \nوأبو سفيان ماشي من المدينة متجه لمكة عدّى على سلمان الفارسي وصهيب الرومي وبلال بن رباح الحبشي وكانوا واقفين مع مجموعة من الصحابة،\nفقالوا:\nوالله ما أخذتْ سيوفُ الله من عنقِ عدو الله مأخذهاَ \nيعني انت لسه عايش ومأخدتش جزاءك ومُت زي باقي أعداء الله إللي قتلهم المسلمين زي أبي جهل وأمية بن خلف وغيرهم من الكفار،\nوإللي بيتكلموا مين\nده مش ناس من أشراف العرب مثلا فممكن الكلمة متأثرش في أبي سفيان، أو يبلعها لهم لأ، ده الثلاثة سلمان وصهيب وبلال مش من العرب أصلا وكمان كانوا عبيد يُباعوا ويُشتروا\nفالموقف كان شديد على أبي سفيان، فسمع كلامهم أبو بكر الصديق رضي الله عنه فقال لهم:\nأتقولون هذا لشيخ قريش وسيدهم؟!!\nهو قال الكلمة دي عشان يتألّف ويكسب قلب أبو سفيان ويستمِيله للإسلام، يعني مكنش عايزه يسمع إللي يُنفّره عن الإسلام،\nفرجع أبو بكر لرسول الله ﷺ وأخبره إللي حصل، فكان رد فعل رسول الله ﷺ مختلف\nقال رسول الله ﷺ لأبي بكر:\n\"يَا أَبَا بَكْرٍ لَعَلَّكَ أَغْضَبْتَهُمْ، لَئِنْ كُنْتَ أَغْضَبْتَهُمْ، لَقَدْ أَغْضَبْتَ رَبَّكَ\"\nيعني رسول الله ﷺ بيقول لأبي بكر إن كلامه ده ممكن يكون زعّل سلمان وصهيب وبلال،\nوالصحابة دول مكانتهم عالية في الإسلام فرضاهم هم أَوْلى من رضِا الكافر؛ لأن ربنا عظّم من شَأْن عبادِه المؤمنين المُتّقين،\nفهو سبحانه يرضى لرضاهم ويغضب لغضبهم\nمنزلة عالية طبعا مش أي حد يوصل لها\nفرجع لهم أبو بكر فَقَالَ: يَا إِخْوَتَاهْ أَغْضَبْتُكُمْ ؟\nيعني هو بيسألهم إذا كانوا زعلوا من كلامه أو الكلام إللي قاله أغضبهم وضايقهم ولّا لأ،\nمقالش مثلا على كيفهم أنا معملتش حاجة غلط\nده راح يستسمحهم ويتأكد من إنهم مش زعلانين مع إن أبا بكر أفضل منهم كلهم أصلا\nفقَالُوا له: لَا ؛ يَغْفِرُ اللهُ لَكَ يَا أُخِي!\nيعني قالوا له لأ مش زعلانين ودعوا له بالمغفرة، وده بيدل على كمال نفوس الصحابة وصفاء قلوبهم،\nوإلا في ناس في موقفهم كانوا ممكن يستغلوا الموقف فيقولوا:\nأه زعلانين ومش مسامحينك وبينا وبينك ربنا\nالصحابة مكنوش كده والثلاثة دول بالذات رسول الله ﷺ شهد لهم بالتقوى والصلاح\nفموقف الصحابة ده بيعلمنا إننا منقفش على كل كلمة تتقال ونُحسن الظن بالمسلمين ونلتمس لهم الأعذار\nرجع أبو سفيان لمكة واجتمع معاه سادات قريش وسألوه:\n ما وراءك؟! يعني عملت إيه\nفحكى لهم أبو سفيان إللي حصل معاه قال:\nًجئتُ محمداً فكلمتُه، فوالله ما ردّ عليّ شيئا \nًثم جئتُ ابنَ أبي قحافةَ فلم أجدْ فيهِ خيرا\nثم جئتُ عمرَ بن الخطابِ فوجَدتُّه أَعدى العدو\nثم جئتُ علياَّ فوجدتُّه أَلْيَن القومِ\nوقد أشارَ عليّ بشئٍ صنعتُه، فوالله ما أدري هل يُغنِي عنِّي شيئاً أم لا\nقالوا: وبم أمَرَك\nقال: أَمرني أن أُجِيرَ بينَ النّاسِ، ففعلتْ\nفقالوا له: فهل أجازَ ذلكَ محمداً؟\nيعني محمد ﷺ وافق وأقرّ إللي انت عملته ده،\nفقال لهم: لا\nقالوا له: وَيْلك، إن زادَ الرجلُ على أن لَعِب بك\nيعني زي ما بنقول كده: يا نهارك أبيض، ده ضحك عليك واستغفِلك\nفقال: لا والله ما وجدت غير ذلك\nيعني بيقول لهم إن مكنش قصاده غير إللي هو عمله ده،\nهنا قريش عرفت إنها في مشكلة جامدة وبقى في احتمال كبير لغزو مكة وهم مش قادرين يعملوا حاجة ومفيش في إيدهم غير انتظار الأحداث الجاية\nده كان الوضع في مكة، طيب الوضع في المدينة كان إيه وإيه إللي رسول الله ﷺ عمله بعد كده\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 188, "l": "الجزء 162 | احداث السنه الثامنه من الهجرة | المسير الي مكه", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_واثنان_وستون\n#أحداث_السنة_الثامنة_من_الهجرة\n#المَسِير_إلى_مكة\nاتكلمنا المرة إللي فاتت عن أبي سفيان لما راح المدينة عشان  يقابل رسول الله ﷺ ويجدد معاه العهد ويمدّه لفترة أطول،\nوبعد محاولات كتير رجع مكة خائبا من غير ما يحقق أي حاجة وفضلت قريش قلقانة ومستنية تشوف رسول الله ﷺ والمسلمين هيعملوا إيه،\nده كان الوضع في مكة، هنرجع بقى لرسول الله ﷺ في المدينة ونشوف هيعمل إيه،\nقلنا إن رسول الله ﷺ انتهز فرصة الأحداث إللي حصلت دي وأخذ القرار بفتح مكة،\nعمل إيه بقى رسول الله ﷺ عشان ينفّذ القرار ده\nأول حاجة رسول الله ﷺ عملها إنه أمر المسلمين إنهم يتجهزوا للخروج للجهاد، حتى إنه أرسل للقبائل القريبة من المدينة وكانت على الإسلام إنهم يتجهزوا،\nلكن مقلش لأي حد لسه هو هيروح فين بالضبط ، يعني يا جماعة اتجهزوا احنا خارجين للجهاد، فين بقى المكان إللي هيتوجهوا له؟ محدش كان عارف\n حتى إن أبا بكر دخل على ابنته عائشة رضي الله عنها، وهي بتحرك بعض جِهاز رسول الله ﷺ  فسألها: \nأي بنية! أَأَمركم رسول الله ﷺ أن تجهزوه؟\nيعني رسول الله ﷺ أمركم إنكم تجهزوا لسفره للغزو،\nقالت له عائشة: نعم، فتجهّز\nيعني انت كمان تجهّز عشان تخرج مع رسول الله ﷺ،\nفسألها : فأين تَرَيْنه يُريد؟\nيعني تفتكري ناوي يروح فين للغزو، فقالت له:\n لا والله ما أدري! يعني هي كمان مش عارفة رسول الله ﷺ هيروح فين،\nلأن رسول الله ﷺ مكنش عايز الأخبار توصل لمكة إن المسلمين هييجوا يفتحوا مكة عشان قريش متجهزش جيش وتحصل حرب،\nوبعد شوية رسول الله ﷺ أخبر الناس إن وجهة الغزوة دي هي مكة عشان يستعدوا بجديّة\nوزيادة بقى في التّمْوِيه عشان المشركين ميعرفوش وجهة رسول الله ﷺ فين بالضبط رسول الله ﷺ أخرَج سرية مكونة من ثمانية رجال من الصحابة بقيادة أبي قتادة  ناحية وادي إِضَم كطليعة للجيش، يعني كأنهم فرقة استكشافية للجيش إللي هييجي بعدين،\nوأرسل رسول الله ﷺ للقبائل إللي طلب منهم يخرجوا معاه للجهاد إنهم يقابلوه في منطقة اسمها مَرّ الظَّهْران على بُعد حوالي اثنان وعشرون كيلو من مكة،\nيعني القبائل هتيجي من طرق مختلفة ويتقابلوا في منطقة مَر الظهران عشان عيون قريش متعرفش حاجة عن الجيش إللي هييجي لمكة،\nوفي رواية تانية برده إنهم تقابلوا مع رسول الله ﷺ وهو خارج من المدينة وانضموا لجيش رسول الله ﷺ،\nالمهم يعني إن الجيش هيبقى مكتمل قبل دخوله مكة\nتجهز الصحابة في المدينة للخروج للقتال، وأمر رسول الله ﷺ إن محدش يُخبر أي إنسان خارج المدينة عن موضوع اتجاه المسلمين لغزو مكة،\nورفع رسول الله ﷺ يده للسماء ودعا وقال:\n \"اللهم خُذْ على أسماعِهم وأبصارِهم فلا يرونا إلا بَغْتة، ولا يسمعون بنا إلا فجأة\"\nيعني رسول الله ﷺ بيدعي ربنا إنه ميخليش قريش تعرف أي حاجة عن المسلمين وجيشهم ويتفاجؤا بالجيش ده،\nوبدأ الإستعداد للخروج من المدينة،\nحصلت هنا حادثة مهمة\nواحد من الصحابة من أهل بدر اسمه حاطِب بن أبي بَلْتَعة كتب رسالة وأعطاها لامرأة عشان توصلها لقريش، والرسالة دي كان مكتوب فيها إن رسول الله ﷺ مجهز جيش وهييجي يغزو مكة\nوحاطب ده لو تفتكروا كان أرسله رسول الله ﷺ برسالة للمقوقس حاكم مصر بيدعوه فيها للإسلام، يعني ده مش واحد عادي، ومع ذلك عمل الخيانة دي،\nأيوة دي خيانة كبيرة جدا لرسول الله ﷺ والمسلمين، يعني مطلّع أسرار الدولة الإسلامية للأعداء\nجاء الوحي لرسول الله ﷺ يخبره إن حاطب بن أبي بلتعة أرسل رسالة مع امرأة لقريش وهي في مكان كذا باتجاه مكة،\nفأمر رسول الله ﷺ علي بن أبي طالب والزبير بن العوام إنهم يروحوا المكان إللي فيه المرأة ويجيبوا منها الرسالة،\nوانطلق علي والزبير لحد ما وصلوا للمرأة ووقفوها وقعدوا يدوروا في المتاع بتاعها الموجود على الدابة ملقوش حاجة فقالوا لها هاتي الرسالة إللي معاكِ\nفطبعا أنكرت وقالت إن معهاش أي رسائل\nفقال لها علي:\n\"إِنِّي أَحْلِفُ بِاللَّهِ مَا كَذَبَ رَسُولُ اللَّهِ ﷺ وَلَا كُذِبْنَا،\nلَتُخْرِجِنَّ الْكِتَابَ أَوْ لَنُلْقِيَنَّ الثِّيَابَ\"\nيعني بيقولها إن رسول الله ﷺ مكذبش علينا لما قال لنا إن معاكِ رسالة ولا الوحي كذب على رسول الله ﷺ وعلينا،\nفطلعي الرسالة وإلا هنفتشك احنا\nفلما المرأة شافت إصرارهم وانهم بيتكلموا جد وفعلا هيفتشوها قالت لعلي والزبير :\nأَعْرِضا!\nيعني التفتوا لمكان تاني عشان أعرف أطلع لك الرسالة، فأعْرَض علي والزبير، \nفالمرأة فكّت شعرها وكانت عاملاه ضفيرة ومخبية الرسالة داخل الضفيرة\nوأعطت لهم الرسالة فأخذوها ورجعوا للمدينة لرسول الله ﷺ وأعطوه الرسالة،\nأرسل رسول الله ﷺ لحاطب بن أبي بلتعة، فجاء حاطب لرسول الله ﷺ، فقال له رسول الله ﷺ:\n\" يَا حَاطِبُ، مَا هَذَا؟ مَا حَمَلَكَ عَلَى هَذَا؟\"\nيعني إيه ده وإيه إللي خلاك تعمل كده؟!!\nفقال حاطب لرسول الله ﷺ:\nيَا رَسُولَ اللَّهِ، لَا تعجل عليَّ، إني كنتُ امرأً مُلْصَقًا فِي قُرَيْشٍ وَلَمْ أكُن من أنفسِها،\nوكان مَن معك من المُهاجرين مَن لهم قرابات يحمون بها أهليهم وأموالهم،\nفأحببتُ إذا فَاتَنِي ذَلِكَ مِنَ النَّسَبِ فِيهِمْ أَنْ أَتَّخِذَ عندهم يدًا يحمون قَرَابَتِي، وَلَمْ أَفْعَلْهُ ارْتِدَادًا عَنْ دِينِي، وَلَا رِضًا بِالْكُفْرِ بَعْدَ الْإِسْلَامِ\"\nيعني حاطب بيقول لرسول الله ﷺ : استنى عليّ يارسول الله واسمعني، أنا حليف لقريش لكني مش من أهل المكة الأصليين،\nوأنا عندي أهل في مكة ضعفاء مفيش حد يحميهم،\nوانت والمهاجرين إللي معاك لكم قرابة وأهل أقوياء يقدروا يحموا نفسهم،\nفأنا حبيت إن يكون ليّ فضل على قريش فيحفظوا جميلي ويحموا أهلي، وربنا هينصرك أصلا سواء أنا قلت لهم أو لأ،\nوأنا معملتش كده عشان أنا منافق أو ارتديت على الإسلام ولا رضيت بالكفر بعد الإسلام\nيعني باختصار هي لحظة ضعف خاف فيها حاطب على نفسه وعلى أهله،\nفقال رسول الله ﷺ:\n\" لَقَدْ صَدَقَكُمْ\"\nيعني هو فعلا صادق في كلامه في إنه لم يكفر ولم ينافق ولكن هي لحظة ضعف منه،\nلكن طبعا مش مبرر إنه عشان يحمي عيلته يخون الله ورسوله وتحصل مجزرة بين المسلمين وبين أهل مكة، \nفي حين إن لو جيش المسلمين دخل مكة فجأة في احتمال كبير إن أهل مكة يدخلوا الإسلام،\nفالموقف هنا مش موقف سهل ولا عادي، حتى عمر بن الخطاب رضي الله عنه إللي كان حاضر الموقف قال لرسول الله ﷺ :\n\" يَا رَسُولَ اللَّهِ، دَعْنِي فَلْأَضْرِبْ عُنُقَهُ؛ فَإِنَّ الرَّجُلَ قَدْ نَافَقَ\"\nيعني خليني أقتله يا رسول الله لأنه نافق وخان الله ورسوله،\nيعني عمر نفسه شايف إن حاطب يستحق القتل بسبب خيانته دي،\nلكن رسول الله ﷺ رد على عمر وقال له\n\" وَمَا يُدْرِيكَ يَا عُمَرُ، لَعَلَّ الله قد اطَّلع على أَصْحَابِ بَدْرٍ يَوْمَ بَدْرٍ فَقَالَ: اعْمَلُوا مَا شِئْتُمْ فَقَدْ غَفَرْتُ لكم\"\nيعني حاطب من أهل بدر وأهل بدر لهم مكانة خاصة عند ربنا وهم كلهم من أهل الجنة وربنا غفر لهم وعفا عن سيئاتهم إللي ممكن يعملوها، وخصوصا إن حاطب كمان اعترف بغلطه وهو معملش كده لأنه نافق أو كفر بالله ورسوله\nورسول الله ﷺ بيعلمنا هنا إن لما يحصل خطأ من أهل الفضل نعذرهم وخصوصا إن الخطأ مش متعمد ولكنه مُتَأَوّل\nيعني حاطب عارف إن الخطاب بتاعه مش هيأثر حاجة في نصر الله لرسوله فعشان كده أرسله،\nونزلت في حاطب الآيات الأولى من سورة الممتحنة:\n\" يَا أَيُّهَا الَّذِينَ آمَنُوا لَا تَتَّخِذُوا عَدُوِّي وَعَدُوَّكُمْ أَوْلِيَاءَ تُلْقُونَ إِلَيْهِمْ بِالْمَوَدَّةِ وَقَدْ كَفَرُوا بِمَا جَاءَكُم مِّنَ الْحَقِّ يُخْرِجُونَ الرَّسُولَ وَإِيَّاكُمْ ۙ أَن تُؤْمِنُوا بِاللَّهِ رَبِّكُمْ إِن كُنتُمْ خَرَجْتُمْ جِهَادًا فِي سَبِيلِي وَابْتِغَاءَ مَرْضَاتِي\"\n☆طيب لو واحد من المسلمين دلوقتي أفشى أسرار المسلمين لأعداءهم وهو متعمد الخيانة يبقى حكمه إيه\nباختصار حكم الجاسوس على خلاف بين العلماء، في علماء قالوا إنه مرتد ويُقتل، وعلماء قالوا إنه لا يُقتل،\nوالصحيح إن الحكم يرجع لإمام المسلمين ويشوف المصلحة فين، يعني لو كان قَتْلُه فيه مصلحة للمسلمين يبقى يقتله ، وإن كان استبقاؤه وعدم قتله أصْلح للمسلمين استبقاه ولا يقتله\n《تفصيل المسألة في رابط في التعليقات\n من موقع الإسلام سؤال وجواب 》\nخرج رسول الله ﷺ من المدينة مع جيش من الصحابة مكون من عشرة آلاف مقاتل متوجهين لمكة، وفي رواية تانية إنهم كانوا اثنا عشر ألف، \nعشرة آلاف من المهاجرين والأنصار لم يَتَخلّف منهم أحد وألفين من القبائل إللي أسلمت،\n☆رقم عشرة آلاف ده مش بيفكركم بحاجة\nفاكرين غزوة الأحزاب إللي كانت من ثلاث سنوات وكان عدد المشركين فيها عشرة آلاف؟!\nأهه الآية اتقلبت دلوقتي وبقى جيش المسلمين المُحاصر لقريش عشرة آلاف مقاتل من الصحابة، نفس العدد لكن فرق كبير جدا بين فريق الإيمان وفريق الكفر\n\"وَتِلْكَ الأَيَّامُ نُدَاوِلُهَا بَيْنَ النَّاسِ\"\nكان خروج رسول الله ﷺ في العاشر من رمضان في السنة الثامنة من الهجرة وكان صائم ﷺ وكان الصحابة كمان صايمين معاه،\nبعد ما خرج رسول الله ﷺ من المدينة بفترة قابل رسول الله ﷺ العباس بن عبد المطلب جاء مع أهله مهاجرا للمدينة، \nفكان هو آخر المهاجرين لأن مفيش هجرة بعد فتح مكة،\nفزي ما خُتِمت النبوة برسول الله ﷺ فالهجرة خُتِمت بالعباس رضي الله عنه،\nوفرح به رسول الله ﷺ فرحا شديدا فهو من أحب الناس إلى قلبه ﷺ،\nواحنا منعرفش هل العباس كان مسلم من أيام بدر زي ماهو كان قايل لرسول الله ﷺ لما أُسر في بدر وكان بقاؤه في مكة السنين دي كلها عشان ينقل لرسول الله ﷺ أخبار قريش،\nولّا هو لسه مسلم دلوقتي وبعد ما أسلم هاجر على طول\nمفيش أي دليل على أي قول من القولين دول،\nلكن الأكيد عندنا إن هو آخر المهاجرين من مكة إلى المدينة،\nفانضم العباس لجيش المسلمين وأكمل أهله هجرتهم نحو المدينة\nبالقرب من منطقة الجَحْفَة قبل مكة بحوالي مائة وثمانين كيلو كان في رجلين التقيا بجيش رسول الله ﷺ واستأذنا للدخول على رسول الله ﷺ، لكن رسول الله ﷺ لم يأذن لهم بالدخول عليه ورفض إنه يقابلهم،\nواحد اسمه أبو سفيان بن الحارث وهو ابن عم رسول الله ﷺ وكمان أخوه من الرضاعة وكان صاحب لرسول الله ﷺ قبل البعثة وكان في بينهم أُلفة، \nلكن بعد البعثة أبو سفيان ده عادَى رسول الله ﷺ وهَجاه وهجى أصحابه، يعني هو شاعر فكان بيقول شعر بيشتم فيه رسول الله ﷺ وأصحابه،\nوأبو سفيان بن الحارث ده يا جماعة غير أبو سفيان بن حرب زعيم مكة، عشان بس محدش يتلغبط\nأما الرجل الثاني إللي كان معاه فهو عبد الله بن أبي أُمَيَّة بن المُغِيرَة وهو ابن عمة رسول الله ﷺ عاتكة بنت المطلب،\nإيه بقى إللي خرّجهم من مكة\nكانوا خارجين متجهين للمدينة عشان يُسلموا عند رسول الله ﷺ ومكنوش يعرفوا بأمر الجيش إللي كان قريب جدا من مكة ده،\nفلما قابلوا الجيش واستأذنوا للدخول على رسول الله ﷺ لم يأذن لهم رسول الله ﷺ ورفض مقابلتهم،\nفلما رفض رسول الله ﷺ مقابلتهم دخل عبد الله بن أمية على أخته أم سلمة وهي أخته من أبيه، وكانت أم سلمة مع رسول الله ﷺ في الغزوة دي،\nفطلب منها إنها تشفع لهم عند رسول الله ﷺ، فدخلت أم سلمة رضي الله عنها على رسول الله ﷺ وقالت له:\n\" يا رسول الله صِهْرُك وابنُ عَمِّك وابن عَمَّتِك وأخوك من الرَّضَاعة وقد جاء الله بهما مُسْلِمَيْنِ لا يكونَا أشْقَى الناسِ بك\" \nيعني اصفح عنهم واقبل منهم وتجاوز عنهم، لأن رسول الله ﷺ كان أهْدر دمهم، يعني أي حد يقابلهم يقتلوه،\nلأن عداوتهم كانت شديدة لرسول الله ﷺ حتى رسول الله ﷺ قال لأم سلمة:\n\" لا حَاجَةَ فِيهمَا، أمَّا ابْنُ عمِّي فهتَكَ عِرْضِيِ، وأما ابْن عمَّتى فَقَالَ لِي بِمَكةَ مَا قَالَ\"\nيعني أنا مش عايزهم، ابن عمي هتك عرضي يعني تكلم بكلام شديد فاحش في عرض رسول الله ﷺ وفي شخصه وكان حسان بن ثابت رد عليه بقصيدة يدافع عن عرض رسول الله ﷺ، \nأما ابن عمته فهو إللي قال لرسول الله ﷺ :\n\" لَن نُّؤْمِنَ لَكَ حَتَّى تَفْجُرَ لَنَا مِنَ الْأَرْضِ يَنبُوعًا ۩ أَوْ تَكُونَ لَكَ جَنَّةٌ مِّن نَّخِيلٍ وَعِنَبٍ فَتُفَجِّرَ الْأَنْهَارَ خِلَالَهَا تَفْجِيرًا ۩ \nأَوْ تُسْقِطَ السَّمَاءَ كَمَا زَعَمْتَ عَلَيْنَا كِسَفًا أَوْ تَأْتِيَ بِاللَّهِ وَالْمَلائِكَةِ قَبِيلًا ۩ أَوْ يَكُونَ لَكَ بَيْتٌ مِّن زُخْرُفٍ\"\nده غير إنه كان بيؤذي المسلمين في أي فرصة بيلاقيها،\nفلما وصل لهما كلام رسول الله ﷺ قال أبو سفيان بن الحارث وكان معاه ابن له:\n\"وَاللَّهِ لَيَأَذْنَنَّ رَسُولُ الله ﷺ أَوْ لَآخُذَنَّ بِيَدِ ابْنِي هَذَا ، ثُمَّ لَنَذْهَبَنَّ فِي الْأَرْضِ حَتَّى نَمُوتَ عَطَشًا أَوْ جُوعًا\"\nيعني والله لو رسول الله ﷺ مرضيش يقابلنا لآخد ابني ده ونمشي في الصحراء لحد مانموت أنا وهو من الجوع أو العطش،\nفلما سمع رسول الله ﷺ كلام ابن عمه، قلبه رق لهما ﷺ وأذن لهم بالدخول عليه، ودخل أبو سفيان بن الحارث وأنشد أمام رسول الله ﷺ بقصيدة يعتذر له فيها ويعلن فيها إسلامه،\nفهم فعلا كانوا جايين ندمانين وعرفوا غلطهم، \nوفي رواية بتقول إن علي بن أبي طالب قال لأبي سفيان بن الحارث إنه يقول لرسول الله ﷺ  ما قال إخوة يوسف ليوسف: \n\"قَالُوا تَاللّهِ لَقَد آثَرَكَ اللّهُ عَلَينَا وَإِن كُنَّا لَخَاطِئِين\"\nفقال أبو سفيان بن الحارث الآية لرسول الله ﷺ، فقال له رسول الله ﷺ:\n\" لاَ تَثرَيبَ عَلَيكُمُ اليَومَ يَغفِرُ اللّهُ لَكُم وَهُوَ أَرحَمُ الرَّاحِمِينَ\"\nوعفا عنهم رسول الله ﷺ وقَبِل إسلامهم\nوصل رسول الله ﷺ لمنطقة الْكَدِيدِ بَيْنَ عُسْفَانَ وَأَمَجَ، كل دي مناطق قريبة من مكة، فلما وصل المنطقة دي شرب الماء  وأفطر بين الناس عشان يشوفوه ويعملوا زيه ،وقال لجيش المسلمين:\n\" إِنَّكُمْ قَدْ دَنَوْتُمْ مِنْ عَدُوِّكُمْ وَالْفِطْرُ أَقْوَى لَكُمْ\"\nيعني انتم قربتم من عدوكم فالأفضل إنكم تفطروا عشان لو حصل وجاء العدو نبقى احنا مستعدين، وطبعا المُفطر أقوى من الصائم في القتال والكر والفرّ\nفبعض الصحابة أفطروا والبعض التاني أكمل صيامه، لأن هنا أمر الصيام مكنش على سبيل الإلزام لكن على سبيل الاختيار،\nلكن لما وصل الجيش منطقة مرّ الظَّهْرَانِ قال للصحابة:\n\"إِنَّكُمْ مُصَبِّحُوا عَدُوِّكُمْ وَالْفِطْرُ أَقْوَى لَكُمْ فَأَفْطِرُوا \"\nيعني خلاص احنا كده هنقابل العدو بالتأكيد فيجب عليكم الفطر وفعلا أفطر الصحابة هنا لأمر رسول الله ﷺ؛ لأن هنا الموضوع مش اختياري\nخدوا بالكم إن الفِطر هنا عشان يتقوُّوا على الجهاد مش عشان السفر، يعني يجوز للمسلم إنه يصوم في السفر عادي لو مكنش عليه مشقة،\nلكن لو عليه مشقة في السفر فيجوز له إنه يفطر ويقضي الصيام بعدين\nلما وصل رسول الله ﷺ لمنطقة مر الظَّهْرَانِ كان وقت العشاء والدنيا ليل، فأمر رسول الله ﷺ الصحابة إنهم يُوقدوا نار لكن مش أي نار\nيعني رسول الله ﷺ كان عايز يعمل لقريش هزيمة نفسية؛ عشان يدخل مكة بأقل الخسائر الممكنة،\nفأمر الصحابة رضي الله عنهم وأرضاهم إنهم يُشعلوا النيران جميعاً، يعني كل فرد منهم يُشعل شعلة ويرفعها بيده\n فبقى في عشرة آلاف شعلة من النيران، والنار بحد ذاتها مرعبة، فلما الناس يشوفوها هيحسوا بالرهبة والخوف وهو ده المطلوب\nفبقى منظر الجيش من بعيد مرعب لأي حد يشوفه\nلحد دلوقتي أهل مكة ميعرفوش حاجة عن جيش رسول الله ﷺ إللي بقى على بُعد اثنان وعشرون كيلو متر فقط من مكة،\nفي الوقت ده كان أبا سفيان قلقان ومش عارف رسول الله ﷺ هيعمل إيه، هو توقع إن ممكن رسول الله ﷺ يأتي مكة بجيش،\n فخرج أبو سفيان خارج مكة عشان يشوف أي حد جاي من طريق المدينة فيسأله عن رسول الله ﷺ وإذا كان خرج في جيش ولّا لأ وكان معاه ساعتها حكيم بن حُزام إللي كان ساعد في نقض صحيفة مقاطعة بني هاشم لو تفتكروا\nخرج أبو سفيان خارج مكة وشاف النيران المشتعلة وكان منظر مهيب جدا بالنسبة له وأصابه الخوف والفزع،\nفي الوقت ده كان خرج بُدَيْل بن وَرْقاء عشان يشوف جيش رسول الله ﷺ جه ولّا لسه لأنه كان عارف إن رسول الله ﷺ مش هيسكت عن إللي قريش عملته،\nفشاف جيش رسول الله ﷺ وشاف أبو سفيان وهو واقف بيبص على جيش رسول الله ﷺ وهو ميعرفش إن ده جيش رسول الله ﷺ \nفيا ترى هيكون رد فعل أبي سفيان إيه لما يعرف إن الجيش الكبير ده جيش رسول الله ﷺ؟!\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 189, "l": "الجزء 163 | احداث السنه الثامنه من الهجرة | ابو سفيان بين القتل  والدخول في الإسلام", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وثلاثة_وستون\n#أحداث_السنة_الثامنة_من_الهجرة\n#أبو_سفيان_بين_القتل_والدخول_في_الإسلام\nوقفنا المرة إللي فاتت عند أبي سفيان لما خرج من مكة عشان كان عايز يقابل أي حد جاي من طريق المدينة ويسأله عن أخبار رسول الله ﷺ وإذا كان جهّز جيش لغزو مكة ولّا ناوي يعمل إيه،\nوكان ساعتها خارج معاه حكيم بن حِزام، ولو تفتكروا حكيم بن حزام ده يبقى ابن أخت خديجة بنت خويلد رضي الله عنها،\nوكان بيساعد المسلمين لما كانوا مُحاصرين في شعب أبي طالب، وكان لحد دلوقتي لسه على الكفر،\nوكان خرج معاهم بُدَيْل بن وَرْقاء عشان يشوف أخبار رسول الله ﷺ هو كمان،\nفلما شاف أبو سفيان بن حرب النار المشتعلة اتفزع وقال \nما رأَيْتُ كاللَّيلةِ نِيرانًا قطُّ\nيعني إيه الجيش الكتير العظيم القوي ده، أنا عمري ما شفت زيه،\nفقال له بُديل:\n\"هذه والله نيران خُزَاعة حَمّشتها الحرب\"\nيعني خُزاعة جاءت بالجيش ده عشان تنتقم من قريش بسبب إللي عملته،\nفقال له أبو سفيان:\nخزاعة واللهِ أذلُّ من أن يكونَ هذه نيرانُهم\nيعني مستحيل تكون خزاعة بالعدد الكبير ده، هم أقل وأحقر من إن ده يكون جيشهم.\nكان مين بقى سامع الحوار ده بين أبو سفيان وبُديل بن ورقاء\nالعباس بن عبد المطلب\nالعباس لما كان شاف رسول الله ﷺ جاي في عشرة آلاف مقاتل قال في نفسه:\nوالله لَئِن دخل رسول الله ﷺ مكة عَنْوَة قبل أن يَسْتأمِنوه إنه لهلاكُ قريش إلى آخرِ الدّهر\nيعني لو رسول الله ﷺ دخل مكة بالقوة مع جيشه القوي ده قريش كلها هتهلك ومش هيبقى لها أي أثر،\nوقريش قبيلة قوية فأكيد إنها تدخل في الإسلام أفضل من إنها تُقتل، وكمان هُم الأهل والعشيرة، ومفيش حد يكره إن أهله يدخلوا في الإسلام بعد ما كانوا كفار\nفبدأ العباس يبحث عن أي شخص يُخبر قريش عن مجِيء رسول الله ﷺ في جيش عشان يخرجوا ويستسلموا له ويطلبوا منه الأمان،\nوطبعا موقف العباس هنا مختلف عن موقف حاطب بن أبي بلتعة لما أرسل برسالة لقريش عشان يُخبرهم بنية رسول  الله ﷺ في غزو مكة،\nلأن دلوقتي الجيش أمره بقى معروف والنيران بتاعته مشتعلة وقريب جدا من مكة،\nومفيش أي نوع من أنواع التّخفّي وأي حد ممكن يعرف عن جيش رسول الله ﷺ\nبعكس الوضع لما كان الجيش لسه مخرجش من المدينة وكان على بُعد أيام من مكة وقريش كانت تقدر تستعد بجيش،\nلكن دلوقتي خلاص مفيش أي وقت للاستعداد، فقريش مش هيبقى قصادها حل غير الاستسلام لرسول الله ﷺ\nفالعباس عايز قريش تستأمن لنفسها، فركب بغلة رسول الله ﷺ وانطلق ناحية مكة عشان يدور على أي حد يُخبر أهل مكة بجيش رسول الله ﷺ عشان يطلبوا منه الأمان،\nفسمع بقى أبو سفيان و بُديل بن ورقاء وهم بيتكلموا\nفعرف صوت أبو سفيان فنادى عليه، فلما سمع أبو سفيان صوت العباس عرفه هو كمان وسأله:\nأبو الفضل؟\nيعني انت العباس بن عبد المطلب؟ طبعا زمان مكنش في أضواء زي عندنا دلوقتي والدنيا ساعتها كانت ليل وضلمة فمحدش كان شايف حاجة\nالمهم العباس رد عليه وأكد له إن هو العباس فعلا، فقال له أبو سفيان:\n\" ما لكَ فداكَ أبي وأمي\"\nيعني بيقوله إيه إللي خرّجك في الوقت المتأخر ده، وعلى فكرة أبو سفيان صديق قديم للعباس ففي بينهم صحوبية وأُلفة،\nوأبو سفيان لحد دلوقتي مكنش يعرف إن العباس خرج مهاجر وبعدين رجع تاني لمكة، فهو مستغرب إيه إللي خرّج العباس من بيته في الوقت ده من الليل،\nفقال له العباس:\nويلَكَ هذا واللهِ رسولُ اللهِ في الناسِ واصباحَ قريشٍ واللهِ لئن دخل رسولُ اللهِ ﷺ مكةَ عَنوة قبل أن يأتوه فيستأمِنوه، إنه لَهلاكُ قريشٍ إلى آخرِ الدهرِ\nيعني الجيش إللي انت شايفه ده جيش رسول الله ﷺ ولو دخل مكة بالقوة مع جيشه ده قبل ما قريش تطلب منه الأمان؛ قريش كلها هتهلك ومش هيتبقى منها واحد حتى،\nفقال له أبو سفيان:\nفما الحيلةُ فداك أبي وأمي\nيعني أعمل إيه انا دلوقتي عشان أطلّع قريش من المشكلة دي،\nفقال له العباس:\n\"لا واللهِ إلا أن تركبَ في عجُزِ هذه الدابةِ فآتي بك رسولَ اللهِ ﷺ فإنه واللهِ لئن ظفر بك ليَضربَنَّ عُنقَكَ\"\nيعني ملكش أي حل غير إنك تركب معايا على البغلة دي وأخدك ونروح لرسول الله ﷺ،\nلأنك لو وقعت في إيده من غير ما يكون معاك أمان ومن غير ما تكون مسلم هيقتلك\nفوافق أبو سفيان بدون أي تردد؛ لأن هو موقفه صعب جداً دلوقتي ومعندوش أي حل تاني \nركب أبو سفيان خلف العباس على بغلة رسول الله ﷺ واتوجهوا ناحية معسكر المسلمين عشان يقابلوا رسول الله ﷺ ورجع حكيم بن حِزام وبُدَيْل بن وَرْقاء لمكة،\nوصل العباس ومعاه أبو سفيان لمعسكر المسلمين وكانوا مُشْعِلين النار زي ما قلنا، فكان كل ما العباس يعدّي على جماعة من المسلمين كانوا يسألوا :\nمَنْ هَذا\nفلما يشوفوا بَغلة رسول الله ﷺ وعليها العباس عم رسول الله ﷺ مكنش حد بيقوم وبيقولوا لبعض ده عم رسول الله ﷺ وعلى بغلة رسول الله ﷺ،\nومحدش واخد باله من أبي سفيان إللي قاعد وراء العباس على البغلة،\nلأن الدنيا ضلمة زي ما قلنا ويادوب النار مبينة بس الجزء الأمامي من البغلة، وشايفين ظل وخلاص فمحدش هييجي في باله إن أبا سفيان موجود مع العباس،\nوفضلوا ماشيين لحد ما وصلوا عند نار عمر بن الخطاب رضي الله عنه\nقال عمر مَن هذا؟ وقام للعباس وبص على مين الموجود ورا العباس على بغلة رسول الله ﷺ، لقاه أبو سفيان\nفقال عمر:\nأبو سفيانَ عدوُّ اللهِ الحمدُ للهِ الذي أمكنَ منك\nيعني انت خلاص كده وقعت في إيدنا ومفيش بينا عقد ولا عهد وانت مش مسلم وبكده يقدروا يقتلوه براحتهم قصاصا للي عمله في المسلمين قبل كده،\nوانطلق عمر لخيمة رسول الله ﷺ بسرعة عايز يوصل قبل العباس عشان العباس ميلحقش يطلب الأمان لأبي سفيان، \nوانطلق العباس بالبغلة هو كمان عشان يلحق يروح لرسول الله ﷺ قبل عمر، وكان سباق بين الاتنين \nوالعباس سَبق عمر لرسول الله ﷺ ودخل عليه ومعاه أبو سفيان، وجاء عمر وراهم على طول وتكلم قبل ما العباس يتكلم وقال:\nيا رسولَ اللهِ! هذا أبو سفيانَ قد أمكن اللهُ منه بلا عقدٍ ولا عهدٍ فدعْني فأضربُ عُنُقَه \nيعني ربنا مكننا من أبي سفيان عدو الله إللي حزّب الأحزاب وحاصر المدينة وقتل المسلمين في أُحد ورضي بالتمثيل إللي حصل في جثثهم، وخلَف العهد مع المسلمين، يعني هو له تاريخ أسود مع المسلمين\nفالعدو ده بقى في إيدينا خلاص بدون ما يكون له عهد ولا أمان فخلينا بقى نقتله قِصَاصًا للي عمله ده كله، يعني عمر كان عايز ينتصر لله عز وجل،\nفهنا العباس قال :\nيا رسولَ اللهِ إني قد أجرْتُه\nيعني هو خلاص بقى في حمايتي دلوقتي يا رسول الله،\nوبعدين العباس راح جنب رسول الله ﷺ وقعد قصاده عشان يكلمه ويقنعه إن يسمع من أبي سفيان ويعطي له الأمان،\nكل ده وعمر بن الخطاب عمال يتكلم ويُلِح ويتحايل على رسول الله ﷺ إنه يقتل أبا سفيان،\n فهنا العباس قال لعمر:\n\"مهلًا يا عمر! واللهِ لو كان رجلٌ من بني عديِّ بن كعبٍ ما قلتَ هذا ولكن قد عرفتَ أنه رجلٌ من بني عبدِ منافٍ\"\nيعني إيه الكلام ده\nعمر بن الخطاب كان من بني عدِي،\nوأبو سفيان كان من أقارب رسول الله ﷺ في النسب، ولو تفتكروا لما هرقل طلب حد من أقارب رسول الله ﷺ قال له أبو سفيان إنه أقربهم لرسول الله ﷺ نسباً،\nفهنا العباس بيقول لعمر إن لو أبو سفيان كان من قبيلته مكنش قال خلينا نقتله وكان هيدافع عنه زي ما العباس بيدافع عن أبي سفيان دلوقتي،\nبس عمر متشجع ومتحمس لقتل أبي سفيان عشان هو مش من قبيلته،\nفهنا عمر قال للعباس كلمة بيوضح له فيها إن العبرة مش بالنسب ولكن العبرة باللي يرضي الله ورسوله، قال عمر:\n\"مهلًا يا عباسُ لَإسلامُك يومَ أسلمتَ كان أحبَّ إليَّ من إسلامِ الخطابِ،\nومَالِي إلّا أني قد عرفتُ أنَّ إسلامَك كان أحبَّ إلى رسولِ اللهِ ﷺ من إسلامِ الخطاب\"\nيعني بيقول له استنى بس وافهم، أنا فرحت بإسلامك يوم ما أسلمت أكتر من فرحي لو أسلم أبي الخطاب،\nيعني أبو عمر لم يُسلم، لكن لو كان أسلم مكنش عمر هيبقى فرحان بإسلامه زي ما هو فرحان بإسلام العباس يوم ما أسلم ،مع إن الواحد بيحب الخير لأبوه والعصبية القبيلية ده من أصل العرب،\nطيب إيه السبب بقى في التفكير بتاع عمر ده\nلأن رسول الله ﷺ بيحب العباس أكتر من حبه للخطاب، وفرح جدا بإسلامه، وفرح رسول الله ﷺ بإسلام العباس أكتر من فرحه بالخطاب لو أسلم،\nيعني عمر بيقوله إن المقياس في حبي لإسلام الناس هو حب رسول الله ﷺ لهم، يعني أنا مشاعري الشخصية مش هي إللي بتتحكم فيّ ولكن ما يحبه الله ورسوله\nفهنا رسول الله ﷺ اتكلم وقال للعباس:\n\"إِذهبْ به إلى رَحلكَ فإذا أصبحتَ فأْتِنا به\"\nيعني خد أبا سفيان وخلّيه عندك وبيّته معاك في رَحلِك والصبح هاته وتعال، وساعتها هنشوف حل للموضوع،\nوفعلا العباس أخد أبا سفيان وراح للخيمة بتاعته وبات هناك معاه للصبح.\n☆عندنا هنا سؤال بقى، يا ترى مين إللي كان رأيه صح؟\nعمر بن الخطاب رضي الله عنه في إنه يقتل أبا سفيان،\nولّا رأي العباس رضي الله عنه في إنه يحمي أبا سفيان من القتل\nاحنا طبعا بنعذر عمر رضي الله عنه في ردة فعله وفعلا معاه حق في إنه يُصِر على قتل أبي سفيان، وأظن لو ناس كتير في موقفه كانت هيكون رد فعلها زي عمر كده\nلكن الرأي الصحيح كان رأي العباس.... ليه\n◇أولا:\nأبو سفيان ممكن يدخل في الإسلام ويَحْسُن إسلامه، \nوإننا نكسب مسلم لصفوف المسلمين وننقذه من النار أحسن من قتله على الكفر ويكون مصيره إلى النار،\nفالغاية مش القتل ولا الانتقام، لكن الغاية هي إنقاذ الناس من النار،\nطيب وبالنسبة للناس إللي اتأذت واتقتلت بسبب واحد زي أبو سفيان فين حقهم\nهم مش خلاص مصيرهم هيكون الجنة؟ هيبقوا عايزين إيه أكتر من دخولهم الجنة\nيعني واحد كافر قتل واحد مسلم في حرب وبعدين الكافر أسلم، فالاتنين خلاص مصيرهم للجنة، لأن المقتول شهيد  وإللي أسلم ده اتمسح عنه سيئاته قبل الإسلام،\nفهل المقتول الشهيد ده هيزعل من قاتله إللي أسلم ده لأنه كان سبب في إنه يموت شهيد\nطبعا لأ \nبالعكس ده هيبقى مُمْتن له لأنه كان سبب في إنه مات شهيد ودي درجة مش أي حد ياخدها\n◇ثانيا:\nلو أسلم أبو سفيان فإسلامه هيكون أصلح لقريش، لأن إسلامه ممكن يؤدي إلى إسلام قريش لأنه سيد مكة،\nوبكده تنجو قريش كلها في الدنيا والآخرة،\nوكمان تُضاف قوة قريش لقوة المسلمين، وده في حد ذاته نصر كبير للمسلمين\n◇ثالثاً: \nلو أسلم أبو سفيان فهيكون إسلامه أحفظ لدماء المسلمين؛ لأن أبا سفيان ممكن يمنع قريش من المقاومة، وبكده تبقى عملية فتح مكة أكتر سهولة\nلكن بقى لو قُتل أبو سفيان فقتله هيُثير قريش لأنه زعيمهم، وكمان هيُثير بني أمية لأنه من أكبر رؤوس بني أمية،\nوساعتها هتحصل حرب كبيرة الله أعلم العواقب بتاعتها هتكون إيه\nولأن رسول الله ﷺ فاهم الكلام ده كويس فهو مَال لرأي العباس رضي الله عنه في عدم قتل أبي سفيان،\nوتعامل رسول الله ﷺ مع قضية أبي سفيان بتوازن رائع يجمع بين الترهيب والترغيب، ويجمع بين القوة والرحمة\nخلونا نشوف الحوار إللي حصل بين رسول الله ﷺ وبين أبي سفيان لما جاء به العباس في اليوم التالي في الصباح زي ما رسول الله ﷺ أمره\nلما جاء العباس بأبي سفيان في الصباح؛ عرض رسول الله ﷺ الإسلام على أبي سفيان بمنتهى القوة وبكلام فيه ترهيب لأبي سفيان قال:\n\"وَيْحك َيا أبَا سفيانَ ألم يأنِ لك أن تشهدَ أن لا إله إلا اللهُ\"\nيعني انت مش شايف إنك لازم تُسلم بقى خلاص\nانتهى خلاص وقت الحوار والإقناع، احنا دلوقتي على باب الحرب، \nرسول الله ﷺ بيعرض الإسلام على أبي سفيان عشان ينجو وإلا فهو دمه حلال دلوقتي لأن قريش خالفت صلح الحديبية وقتلوا رجالاً من خُزاعة،\n وأبو سفيان مش رجل سهل ده من دُهاة العرب، فعرف يُقيّم الموقف وبدأ يرد بطريقة فيها تلطّف مع رسول الله ﷺ و رَدّ بكلام بيجمع بين الموافقة وعدم الاقتناع الكامل في نفس الوقت،\nيعني أنا متفق معاك بس مش مقتنع أوي يعني\nقال أبو سفيان لرسول الله ﷺ:\n\" بأبي أنت وأمي فما أحلمَكَ وأكرمَكَ وأوصلَكَ أما واللهِ لقد كاد يقعُ في نفسي أن لو كان مع اللهِ غيرُه لقد أغنى شيئًا بعدُ\"\nكلمة 《بأبي أنت وأمي》 دي معناها فِداك أبي وأمي والعرب متعودين يدعوا بيها لبعض،\nوقعد أبو سفيان يمدح في بعض فضائل رسول الله ﷺ، يعني هو بيتعجب من صبر وحِلم رسول الله ﷺ وبيتعجب من كثرة كرم رسول الله ﷺ ووصله لرحم من قطع رحمه،\nيعني بعد ده كله رسول الله ﷺ لسه بيُعطي أبا سفيان فرصة إنه يمسح كل إللي عمله بإسلامه ومراعي صلة الرحم إللي أبو سفيان نفسه مكنش مراعيها بينه وبين رسول الله ﷺ،\nوبعد ما مدح أبو سفيان رسول الله ﷺ قال لرسول الله ﷺ إنه 《كاد أن يقتنع》 هو لسه مش مقتنع أوي يعني\n إنه لو كان في آلهة تانية مع ربنا تشاركه في ملكه كانت ساعدته دلوقتي في المحنة إللي هو فيها\nفانتقل بقى رسول الله ﷺ معاه للنقطة الأصعب وهي الاعتراف بنبوته ﷺ، وهي أصعب لأن العرب مكنوش بينكروا إن ربنا هو الخالق الرازق ولكنهم كانوا بيشركوا معاه عبادة الأصنام، أما فكرة النبوة والرسالة فكانت مرفوضة عندهم تمااااما\nفقال له رسول الله ﷺ:\n\"ويلكَ يا أبا سُفيانَ! ألمْ يأْنِ لك أنْ تَشهَدَ أنِّي رسولُ اللهِ؟\"\nلحد اللحظة دي أبو سفيان لسه مش مقتنع أوي بقضية الإيمان الكامل بالإسلام وفي نفس الوقت مش عايز يكذب لأنه زي ماحنا عارفين إنه كان بيترفّع عن الكذب،\nلكنه مش عايز ياخد موقف حاد مع رسول الله ﷺ ويكون فيه نهايته، فاتكلم بلطف ولين وقال لرسول الله ﷺ:\n\" بأبي أنت وأُمِّي ما أحلمَك وأكرمَك وأوصلَكَ أما واللهِ هذه فإنَّ في النفسِ منها حتى الآن شيئًا\"\nيعني أبو سفيان مدح رسول الله ﷺ مرة تانية وقال له إنه مش مقتنع بنبوة رسول الله ﷺ ولسه عنده شك في الإسلام، \nوفي اللحظة دي تدخل العباس؛\nلأنه عارف صعوبة موقف أبي سفيان وإن احتمال قتله وارد فعايز ينقذه ويساعده فقال له :\n\"ويلَكَ! أسلِمْ واشهد أن لا إله إلا اللهُ وأنَّ محمدًا رسولُ اللهِ قبل أن يُضرَبَ عُنُقُكَ\" \nيعني إلحق نفسك وادخل في الإسلام قبل ما تُقتل مفيش وقت للتردد بتاعك ده،\n☆وطبعا يا جماعة ده مش إكراه في الدين عشان محدش يفهم غلط بس\nده الكلام ده كله رحمة بأبي سفيان؛ لأن قتل أبي سفيان في الموقف ده محدش يقدر يستنكره،\nلأن أبا سفيان في الوقت ده يُسمى في عُرف الدول في زماننا دلوقتي مجرم حرب؛ لأنه دبّر اغتيالاً جماعياً قبل كده لسكان المدينة في غزوة الأحزاب،\nده غير فتنة الناس عن دينهم طول سنوات مكة والمدينة، وكمان نقضه العهد مع رسول الله ﷺ في صلح الحديبية،\nيعني هو حلال الدم زي ما قلنا من شوية، وإسلامه هيرفع عنه عقوبة مُستحقة وله الاختيار برده\nفلأن أبو سفيان رجل واقعي وعارف أد إيه موقفه خطير على طول نطق الشهادتين بعد كلام العباس ودخل في الإسلام\nلكن واضح كده إن دخول أبي سفيان في الإسلام كان دخول اضطراري\nيا ترى بقى هل هيقتنع أبو سفيان بالإسلام اقتناع كُلي ولّا هيرجع في كلامه، وهيعمل إيه مع قريش؟!\nده إللي هنعرفه الجزء الجاي إن شاء الله"}, {"n": 190, "l": "الجزء 164 | احداث السنه الثامنه من الهجرة | دخول رسول الله مكه فاتحا", "u": "", "t": "#قصص_الأنبياء(٢)\n#السيرة_النبوية\n#الحلقة_مائة_وأربعة_وستون\n#أحداث_السنة_الثامنة_من_الهجرة\n#دخول_رسول_الله_مكة_فاتحا\nوقفنا المرة إللي فاتت عند دخول أبي سفيان للإسلام، وشوفنا إن دخوله كان دخول اضطراري،\nفالعباس كان عايز يهوّن شوية على أبي سفيان ويستمِيل قلبه ويثبته على الإسلام فقال لرسول الله ﷺ:\n\"يا رسولَ اللهِ! إنَّ أبا سفيانَ رجلٌ يُحبُّ هذا الفخرَ فاجعلْ له شيئًا\"\nيعني أبو سفيان بيحب التباهي بين الناس، فأعطيه شيء يفتخر ويبقى مبسوط بيه بين الناس ،\nفقال رسول الله ﷺ:\n\"نعم، مَن دخل دارَ أبي سفيانَ فهو آمِنٌ ومن أغلق عليه بابَه فهو آمِنٌ، ومن دخل المسجد الحرام فهو آمن\"\nيعني أي حد من أهل مكة هيدخل دار أبي سفيان هيكون آمن من القتل، وأي حد هيقفل عليه باب بيته أو يدخل البيت الحرام هيكون آمن من القتل\nعلى فكرة احنا لو ركزنا هنلاقي إن مفيش فرق يعني بين إن الواحد يقفل عليه بابه وبين إنه يروح بيت أبي سفيان\nيعني النتيجة واحدة أصلا\nلكن رسول الله ﷺ خصّ أبا سفيان بذكر بيته هو بالذات كنوع من الشرف،\nوخدوا بالكم إن إللي عمله رسول الله ﷺ ده بإنه أعطى لأبي سفيان حاجة يفتخر بيها كان تصرف حكيم منه ﷺ \nليه\nلأن رسول الله ﷺ شاف إن أبا سفيان أسلم وهو في موقف المضطر، يعني معندوش حل تاني غير إنه يدخل في الإسلام، يعني لسه مش مقتنع بالنبوة ولا حاسس بالانتماء الحقيقي للإسلام،\nوبسبب كده ممكن أبو سفيان ينتهز أي فرصة للانقلاب على المسلمين\nوكمان مننساش إن أبا سفيان زعيم مكة بقاله سنين فلو رسول الله ﷺ لم يعطه مكانته فبالتأكيد ده هيأثر تأثير سلبي على أبي سفيان وعلى أهل مكة كلهم،\nده غير بقى إن رسول الله ﷺ لما أعطى لأبي سفيان الشرف والفخر بإن إللي يدخل بيت أبي سفيان فهو آمن، هو كده بيستخدمه لصالح الإسلام،\nبمعني إن أبا سفيان بعد الموقف ده هيبقى من رجال الإسلام و وُلاتِه بدل ما يكون من أعدائه،\nورسول الله ﷺ كده كده مخسرش حاجة لما أعطاه الشرف ده،\n يعني هي حاجة تنفع ولا تضر ولا تقدم ولا تؤخر شيء عند المسلمين لكنها تكسب قلب أبي سفيان\nوزي ما هنشوف إن شاء الله إن المنحة إللي رسول الله ﷺ أعطاها لأبي سفيان دي هتكون سبب في إن أبا سفيان هيدفع الناس لدخول بيوتهم وعدم مقاومة المسلمين ويبقى سهل على رسول الله ﷺ فتح مكة بدون مقاومة وسفك دماء،\nده غير بقى إن الشرف إللي رسول الله ﷺ أعطاه لأبي سفيان ده وراه معنى خطير\nوالمعنى ده هو :\nفرض حظر التجوال المؤقت على أهل مكة\nيعني يا جماعة طول ما الواحد فيكم داخل بيته أو في المسجد الحرام أو في بيت أبي سفيان فهو في أمن مِن القتل،\nطيب وإللي هيبقى برة البيت في الطريق \nده بقى غير آمن وساعتها منعرفش ممكن نعمل فيه إيه، وطبعا حظر التجوال ده عشان رسول الله ﷺ عايز يمنع الناس من أي فرصة للمقاومة وكمان عايز يمنع القتل العشوائي في أهل مكة،\nيعني باختصار عايز يتم فتح مكة بأقل الخسائر الممكنة من الطرفين\nالعباس لما قام عشان يمشي مع أبي سفيان، رسول الله ﷺ قال له:\n\" يا عباس! احبِسْه بمَضِيقِ الوادي عند حَطيِمِ الجُندِ حتى يمرَّ به جنودُ اللهِ فيراها\"\nيعني رسول الله ﷺ بيقول للعباس إنه يخلي أبا سفيان يقعد يستنى عند مكان معين عشان يشوف الجيوش الإسلامية وأعدادها وعُدّتها وتنوّع أفرادها، \nعايزه يشوف الأحزاب المؤمنة ويشوف الفرق إللي بينها وبين الأحزاب إللي هو كان جامعها من ثلاث سنوات فقط\nوالسبب في إن رسول الله ﷺ عايز يخلي أبا سفيان يشوف الجيش وتجهيزاته هو إنه مش عايز يسيب فرصة للشيطان مع أبي سفيان \nيعني مش عايز الشيطان يلعب في دماغ أبي سفيان ويخليه يرجع عن إسلامه بأي طريقة؛ فرسول الله ﷺ عايز يزلزل معنويات أبي سفيان وبالتالي مش هيبقى عنده أي أمل في المقاومة ويعرف إنه ملوش طاقة في قتال جيش رسول الله ﷺ \nأخذ العباس أبا سفيان وراحوا عند المكان إللي رسول الله ﷺ قاله عليه،\nرسول الله ﷺ بقى قسم الجيش على هيئة قبائل، يعني جَعل جنود كل قبيلة مع بعض تحت لواء وراية واحدة،\nوقف أبو سفيان يشوف العرض العسكري للجيش الإسلامي وهو معدي من قصاده،\nوانبهر أبو سفيان انبهار شديد جدا لما شاف الجيش وفعلا فَقَد أي أمل في المقاومة زي ما كان رسول الله ﷺ عايز،\nوانبهاره مكنش عشان العدد كبير فقط ودي أول مرة يشوف عشرة آلاف مقاتل،\nوإلا فهو نفسه قاد جيش قبل كده بنفس العدد\nلكن انبهاره كان بسبب:\n◇أولا:\nإن ربنا عز وجل يُلقي الجلال والرهبة والهيبة على جنوده سبحانه وتعالى، \nيعني في ناس لما نشوفهم نحس إن عليهم هيبة كده، فربنا بقى بيُلقي الهيبة والرهبة دي على جنوده، وبالتالي أعداء الدين بيُصابوا بالرعب ويشوفوا القوة البسيطة من المسلمين قوة هائلة\n◇ثانيا:\nأبو سفيان شاف عِدة قبائل كان في بينهم وبينه علاقة قوية ومكنش في بينهم أي عداء يُذكر وفجأة القبائل دي تجتمع تحت راية رسول الله ﷺ لقتال قريش \n◇ثالثا:\nوِحدة الصف إللي شافها أبو سفيان في جيش المسلمين على اختلاف طبيعتهم وقبائلهم، الكل على قلب رجل واحد، القوة والأُلفة والصلابة ظاهرة في مشيتهم وفي تصميمهم وحركتهم\nتعالوا كده نشوف أبو سفيان قال إيه لما شاف جيش المسلمين وهو بيتحرك قصاده\nبدأت القبائل تمُر على أبي سفيان قبيلة قبيلة وكل قبيلة معاها رايتها،\nفكل ما تعدّي قبيلة من أمام أبي سفيان يسأل العباس إللي كان واقف معاه: مَن هذه يا عباس\nفكان العباس يُسمي القبيلة، قال : بنو سُلَيمٍ\nفقال له أبو سفيان: ما لي ولِبَني سُلَيمٍ\nيعني إيه إللي جابهم هنا، ده احنا مفيش بيننا مشاكل، واحنا لوحدنا منقدرش على قتال بني سليم لأنها قبيلة قوية،\nفعدت القبيلة إللي بعدها، فقال أبو سفيان:\n يا عباس! من هذه\nفقال له العباس: مُزَينةُ \nفقال أبو سفيان: ما لي ولمُزَينةَ\nواستمر الوضع على كده، تعدي القبيلة وأبو سفيان يسأل العباس، والعباس يخبره وأبو سفيان يقول ما لي ولبني فلان،\nلحد ما جاءت الكتيبة الخضراء\nمجموعة كبيرة من المقاتلين كلهم متغطيين بالسلاح مش ظاهر منهم غير عنيهم فقط، عشان كده كان اسمهم الكتيبة الخضراء،\nفلما شافهم أبو سفيان قال للعباس:\n\"سبحان اللهِ من هؤلاءِ يا عباس؟ ما لأحدٍ بهؤلاءِ قِبِلٌ\"\nيعني بيقول للعباس مين الكتيبة دي، ده همّ لوحدهم مفيش حد هيقدر عليهم،\nفقال له العباس: \nهذا رسولُ اللهِ ﷺ في المُهاجرينَ والأنصارِ\n☆أيوة فعلا أبو سفيان معاه حق، محدش يقدر على رسول الله ﷺ والمهاجرين والأنصار\nرسول الله ﷺ والمهاجرين والأنصار إللي اتعرضوا للابتلاءات المختلفة على مدى واحد وعشرين سنة في مكة والمدينة...اتعرضوا للتعذيب والقتل والتهجير من بيوتهم وفقدوا أموالهم وبيوتهم وفقدوا أصحابهم وعاشوا في فقر لحد ما أكلوا ورق الشجر،\nكل سنين الابتلاء دي عشان تيجي لحظة التمكين إللي احنا بنتكلم عنها دلوقتي دي،\nإللي متوقع النصر والتمكين من غير ما يعدّي على سنين من الابتلاءات المختلفة والإعداد والتخطيط والتربية الإيمانية زي رسول الله ﷺ والمهاجرين والأنصار كده يبقى بيحلم\nرسول الله ﷺ والمهاجرين والأنصار عشان يوصلوا لمرحلة فتح مكة دي قعدوا واحد وعشرين سنة،\nفما بالكم بغيرهم، وسنن ربنا الكونية لا تتبدل ولا تتغير وربنا لا يَعجل بعجَلِة أحد، \nيعني مش عشان في حد مستعجل النصر والتمكين فربنا هيعجل له النصر والتمكين، لأ...كل حاجة لها وقتها وإللي هيمشي في نفس طريق رسول الله ﷺ والمهاجرين والأنصار هيوصل لنفس النتيجة إللي وصلوا لها\nأما بقى إللي هيدور على طريق مختصر فمش هيوصل وهيتوه للأسف، وانتم شايفين ناس تايهة كتيييير أوي في زماننا دلوقتي لأنهم مشيوا إما في طريق غلط أو حبوا يختصروا الطريق فتاهوا\nشوفوا كده ربنا بيقول إيه:\n\" وَأَنَّ هَٰذَا 《صِرَاطِي  مُسْتَقِيمًا 》فَاتَّبِعُوهُ ۖ \n《وَلَا تَتَّبِعُوا السُّبُلَ 》فَتَفَرَّقَ بِكُمْ عَن سَبِيلِهِ \"\nهو طريق واحد مستقيم ...طريق رسول الله ﷺ، غير كده هنضيع \nكانت كتيبة الأنصار قائدها سعد بن عبادة سيد الخزرج، وهو كان حامل الراية، فلما عدّى على أبي سفيان قال له:\n\"يا أبَا سُفْيَانَ، اليومَ يَوْمُ المَلْحَمَةِ، اليومَ تُسْتَحَلُّ الكَعْبَةُ\"\nيعني النهاردة هنوريكم جزاءكم وهتشوفوا هنعمل فيكم إيه بعد إللي عملتوه في المسلمين السنين إللي فاتت دي\nوعلى فكرة كلام سعد يعتبر كلام منطقي ومقبول بسبب إللي قريش عملته قبل كده في المسلمين،\nومننساش إللي قريش عملته في سعد بن عبادة نفسه بعد بيعة العقبة الثانية لما مسكوه وقعدوا يضربوا فيه لو تفتكروا،\nفأكيد الموضوع سايب أثر في نفسه،\nفالكلام ده أرعب أبا سفيان، وأثّر في نفسه وقال للعباس:\n\"يا عباس! حبَّذا يومُ الذِّمار\"\nيعني ياريت عندي قوة أقدر أحمي بيها قومي وأمنعهم من إن حد يعتدي عليهم\nوبعد شوية والجيش بيمر جاء رسول الله ﷺ مع باقي الجيش من المهاجرين بعد ما مر سعد بن عبادة،\nوهنا قال أبو سفيان لرسول الله ﷺ:\n\"ألم تَعلمْ ما قالَ سعدُ بنُ عُبادةَ\"\nيعني عرفت سعد بن عبادة قال إيه، ورسول الله ﷺ مكنش يعرف سعد قال إيه ، فحكى له أبو سفيان إللي قاله سعد، فقال له رسول الله ﷺ:\n\" كَذَبَ سَعْدٌ، ولَكِنْ هذا يَوْمٌ يُعَظِّمُ اللَّهُ فيه الكَعْبَةَ، ويَوْمٌ تُكْسَى فيه الكَعْبَةُ \"\nيعني رسول الله ﷺ بيقول لأبي سفيان إن سعد أخطأ في الكلام إللي قاله والنهاردة يوم هنعظم فيه الكعبة ونحترمها؛ لأن رسول الله ﷺ مجاش عشان يحتل الكعبة أو إنه جاي ينتقم من أهلها ولكن غرضه نصرة دين الله وعزة أهلها بالإسلام،\nهنا رسول الله ﷺ لما شاف الروح القتالية إللي عند سعد بن عبادة خاف إن الجيش إللي معاه يتأثر بيه فيتساهلوا في القتل ويحصل قتال بدون أي داعِ وهو ﷺ مش عايز يحصل أي قتال إلا لو اضطر للقتال ده،\nفأخذ رسول الله ﷺ الراية من سعد بن عبادة عشان يؤكد للجميع إن موضوع القتال مرفوض تماما إلا في حدود ضيقة،\nولأن رسول الله ﷺ حكيم جدا فهو كان عارف إن نزع الراية هيأثر في نفس سعد ونفس الأنصار، فأعطى الراية لابن سعد وهو قيس بن سعد بن عبادة\nطيب ليه بقى رسول الله ﷺ أعطى الراية لابن سعد بالذات ولم يُعطها لغيره\nلأن الإنسان بطبيعته مبيرضاش إن حد يكون أحسن منه غير ابنه،\nفهنا لما رسول الله ﷺ أخذ الراية من سعد وأعطاها لابنه هو كده طيّب خاطر  سعد وبالتالي لم يؤثر نزع الراية من سعد على سعد نفسه ولا على أحد من الأنصار\nنرجع بقى لأبي سفيان بعد ما شاف جيش رسول الله ﷺ بالكامل قال إيه،\n قال ابو سفيان للعباس:\n\"واللهِ يا أبا الفضلِ لقد أصبح ملكُ ابنِ أخيك الغداةَ عظيمًا\"\nأبو سفيان مفكر إن إللي رسول الله ﷺ فيه ده هو مُلك لأنه لسه مش مستوعب معنى النبوة والرسالة وإن يعني إيه ربنا ينصر جنوده، فقال للعباس إن ملك رسول الله ﷺ عظيم جدا،\nفقال له العباس:\n\"وَيلَك يا أبا سُفيانَ! إنَّها النُّبوَّةُ\"\nيعني إللي رسول الله ﷺ وصل له ده مش مُلك ده الرسالة والنبوة وإن ربنا هو إللي نصره بعد السنين دي كلها،\nفقال له أبو سفيان: فنعم\nيعني معاك حق، وهنا العباس قال لأبي سفيان:\n\" التجأْ إلى قومِك اخرُجْ إليهم\"\nيعني ارجع لقريش بقى وقل لهم يستسلموا لرسول الله ﷺ، فرجع أبو سفيان لقريش وقعد يصرخ فيهم ويقول:\n\" يا معشرَ قريشٍ هذا محمدٌ قد جاءكم فيما لا قِبَلَ لكم به فمن دخل دارَ أبي سفيانَ فهو آمنٌ\"\nيعني أبو سفيان عمل إللي رسول الله ﷺ كان عايزه منه بالضبط\nمنَع قريش من المقاومة وبكده يحقن دماء المسلمين ودماء قريش، وأظهر فخره إللي رسول الله ﷺ أعطاه له وقال إن إللي يدخل دار أبي سفيان فهو آمن،\nفي اللحظة دي بقى خرجت هند بنت عتبة زوجة أبي سفيان من بيتها وتوجهت نحو أبي سفيان وكانت من أشد المقاومين للإسلام ومن أشد المحاربين له، ومسكته من شارِبه وقالت للناس:\n\" اقتُلوا الحَمِيتَ الدَّسِمَ فبئسَ طليعةُ قومٍ\" \nيعني اقتلوا الرجل السمين الضخم ده، فهو أسوأ مَن يكون طليعة لقومٍ في حرب، \nوالطليعة معناها الرجل أو المجموعة إللي بيكونوا في مقدمة الجيش عشان يستطلعوا ويعرفوا أخبار العدو،\nفقال أبو سفيان لقريش:\n\"ويْلَكم لا تغرَّنَّكم هذه من أنفُسِكم وإنه قد جاء ما لا قِبَلَ لكم به، من دخل دارَ أبي سفيانَ فهو آمِنٌ\"\nكلمة ويلكم هي كلمة للتحذير، فبيقولهم متخلوش هند تخليكم تغتروا بقوتكم، فمهما كانت قوتكم فقد جاءكم الأقوى منكم وإللي مش هتقدروا انتم عليه،\nوكرر عليهم إن إللي هيدخل دار أبي سفيان فهو آمن من القتل،\nفقالوا له:\n\"قاتلَك اللهُ وما يُغني غناءُ دارِك\"\nيعني هو بيتك هيكفي مين ولّا مين، بيتك مش هيكفي كل أهل مكة، فقال لهم:\n\"ومن أغلق عليه بابَه فهو آمِنٌ\"\nيعني ده أمان عام لكل واحد هيقعد في بيته ويعتزل الحرب\n☆سبحان الله، أبو سفيان دلوقتي بقى هو المدافع عن دخول رسول الله ﷺ لمكة وهو إللي فتح له طريق الدخول لمكة\n مين كان يصدق إن هييجي اليوم إللي زعيم مكة هيفتح الطريق لرسول الله ﷺ عشان يدخل مكة،\nهل حد من الصحابة كان يتوقع كده يوم ما كانوا خارجين مُطاردين من مكة خايفين حد من قريش يشوفهم،\n《وتلك الأيام نُداوُلها بين الناس》\n بعد ما كانت قريش بيخوّفوا المسلمين المستضعفين بقوا همّ دلوقتي إللي خايفين من المسلمين\nوطرقات مكة بقت فاضية من الناس إللي كانوا بينشروا الرعب والتعذيب والاضطهاد والقتل ضد المسلمين،\nدلوقتي مش هيمشي في الطّرق دي غير المؤمنين\nلما اقترب رسول الله ﷺ من مكة بالتحديد عند مكان اسمه ذي طُوى أوقف راحلته، يعني وقف بالبعير إللي كان راكب عليه في المكان ده ووطّى رأسه خضوعا لله وذُلاّ وتواضعا وشكرا له،\nمعملش زي ما الجبابرة بيعملوا لما يدخلوا بلد ويبقوا مستكبرين ويطغوا في الأرض ويستبيحوا كل شيء دون أي رحمة\nوهنا في المكان ده بدأ رسول الله ﷺ يجهز خطته العسكرية للدخول إلى داخل مكة فقسم جيش المسلمين إلى أربعة فرق:\n◇الفرقة الأولى:\nفرقة فرسان قوية جدا، والقائد بتاعهم خالد بن الوليد سيف الله رضي الله عنه، والفرقة دي هتدخل مكة من ناحية الجنوب أو من أسفل مكة.\n◇الفرقة الثانية:\nفرقة فرسان هي كمان وكان قائدهم الزبير بن العوام حوارِي رسول الله ﷺ ، والفرقة دي مطلوب منها وتدخل من كَدَاء شمال مكة، وأمره إنه يَغرز رايته بالحجون، ويستنى هناك لحد ما يأتيه رسول الله ﷺ.\nوالفرقتين دول بالطريقة دي بيحاصروا مكة كأنها بين فكّي كماشة\n◇الفرقة الثالثة: \nهي فرقة من الرجّالة أو المُشاة ، يعني الجنود إللي بيمشوا على الأرض، والفرقة دي كانت بقيادة أبي عبيدة بن الجراح رضي الله عنه أمين الأمة،\nوأمرهم رسول الله ﷺ إنهم يسيروا نحو بطن الوادي، وبطن الوادي ده هو المنطقة من الحُجون إلى جهة المَسعى بين الصفا والمروة.\n◇الفرقة الرابعة:\n فرقة الأنصار رضي الله عنهم، وكان قائدهم قيس بن سعد بن عبادة زي ما قلنا من شوية، وفي الفرقة دي كان يسير معاهم رسول الله ﷺ.\nأصدر رسول الله ﷺ ثلاثة أوامر لكل الفرق:\n◇الأمر الأول:\n《 لا تقاتلوا إلا من قَاتَلكم》\nيعني لو حد قاتلكم قاتلوه محدش قاتلكم لا تقاتلوا ولا تقتلوا أحد،\nلأن الغرض من فتح مكة مكنش الانتقام زي ما قلنا، الغرض كان حكم البلد ده بالإسلام وتعليم الناس دين رب العالمين\n◇الأمر الثاني: \n\"إذا لقيتم أَوْباش قريش الذين يقاتلون فاحصدوهم حصداً.\"\nأَوْباش قريش هم الفقراء والعبيد وعوام الناس، جمعهم عكرمة بن أبي جهل وصفوان بن أمية بن خلف وسهيل بن عمرو وقرروا إنهم يحاولوا يقاتلوا جيش المسلمين يمكن محاولتهم تنجح،\nفكانت حسابات عكرمة وصفوان إن المحاولة دي لو نجحت خلاص يبقى النصر ده للسادة، ولو حصلت الهزيمة هيتفاوضوا مع لرسول الله ﷺ،\nولو حصلت هزيمة شديدة يعني والناس قُتلت فهيبقى عادي بالنسبة لهم لأن الجيش من أوباش الناس إللي ملهمش قيمة عندهم،\nعادي يعرضوهم للخطر ويضحوا بيهم عشان يحققوا مصلحتهم\nفرسول الله ﷺ إللي أمر جيشه إنه ميقاتلش حد وده منتهى الرحمة أمرهم برده إنهم يقضوا تماما على أي حد يواجههم بكل حزم وقوة،\nفأهل الباطل لازم يشوفوا قوة المسلمين وساعتها هيلينوا ويستسلم القادة\nولم يواجه المسلمون أي جيش لمكة غير المجموعة الصغيرة دي وواجهها خالد بن الوليد وقضى عليها،\nوهرب عكرمة وصفوان وسهيل بن عمرو من خالد بن الوليد، بعد ما عرفوا يقتلوا رجلين من المسلمين كانوا انفصلوا عن جيش خالد فهجم عليه الأوباش دول وقتلوهم رضي الله عنهم،\nوانهزم باقي الأوباش وهربوا ورموا سلاحهم دخلوا بيوتهم  وقفلوا عليهم عشان يأمنوا على أنفسهم؛ لأنهم كانوا عارفين إن إللي يدخل بيته هيكون آمن من القتل.\n◇الأمر الثالث إللي أمره رسول الله ﷺ:\n\" إهدار دم مجموعة من كفار مكة\"\nيعني مجموعة من الأشخاص من أهل مكة أمر رسول الله ﷺ بقتلهم حتى لو كانوا متعلقين بأستار الكعبة،\nمع إن رسول الله ﷺ قال إن مَن دخل البيت الحرام فهو آمن، لكن المجموعة دي مُستَثْناة من أمن رسول الله ﷺ،\nوالسبب في كده إنهم عملوا جرائم لا تُغتفر في حق دولة الإسلام، \nوكانوا أربعة رجال وامرأتين، وهنعرف قصتهم إن شاء الله لما ييجي وقتهم\nدخل رسول الله ﷺ لمكة وكان راكب وراه على راحلته أسامة بن زيد بن حارثة رضي الله عنه ويمشي جنبه بلال بن رباح،\nوكان رسول الله ﷺ بيقرأ سورة الفتح وهو راكب على ناقته ويكررها:\n\"إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا \"\nونزل رسول الله ﷺ بأعلى مكة ونصبوا له خيمة في المكان ده عند الحُجون،\nولما دخل رسول الله ﷺ لمكة كان أهل مكة كلهم سمعوا كلام أبي سفيان فكانوا إما في بيوتهم أو في المسجد الحرام.\nيا ترى بقى إيه إللي رسول الله ﷺ ناوي يعمله مع أهل مكة، وإيه الأحداث إللي هتحصل بعد كده،\nده إللي هنعرفه الجزء الجاي إن شاء الله"}]);
